import type { Mode, ModelId, ProjectRole, RunStatus, Suggestion, ThinkingLevel, Usage } from '@/shared/protocol';

export interface User {
  id: string; email: string; name: string; role: 'admin' | 'member'; disabled?: boolean;
  limits?: { dailyTokens?: number | null; models?: string[] | null; modes?: Mode[] | null };
  createdAt?: string; lastSeenAt?: string | null;
}
export interface Project {
  id: string; slug: string; name: string; description: string; color: string; icon: string;
  previewPort: number; previewCommand?: string | null; previewStrip?: boolean; links?: string[];
  archived?: boolean; createdAt: string; lastActiveAt?: string | null; myRole: ProjectRole | 'admin';
}
export interface GraphNode {
  id: string; slug?: string; name: string; color: string; icon?: string;
  status: 'idle' | 'running' | 'error'; activity: number; lastActiveAt?: string | null;
}
export interface Graph { nodes: GraphNode[]; links: { source: string; target: string; kind: string }[] }
export interface Conversation {
  id: string; projectId: string; title: string; claudeSessionId?: string | null;
  model: ModelId; mode: Mode; createdAt: string; updatedAt: string;
}
export interface Attachment { id: string; filename: string; mime: string; size: number; url: string; thumbUrl?: string }
export interface Run {
  id: string; status: RunStatus; model: string; mode: Mode; startedAt: string; endedAt?: string | null;
  inputTokens: number; outputTokens: number; cacheRead: number; cacheWrite: number; costUsd: number; durationMs?: number | null;
}
export interface StoredEvent { seq: number; type: string; data: any }
export interface Message {
  id: string; conversationId: string; role: 'user' | 'assistant'; content: string; attachments: Attachment[];
  runId?: string | null; createdAt: string; userName?: string;
  run?: Run | null; events?: StoredEvent[]; suggestions?: Suggestion[];
}
export interface PromptRequest { text: string; attachments: string[]; model: ModelId; mode: Mode; thinking: ThinkingLevel }
export interface ModelInfo { id: string; label: string }
export interface UsageSummary {
  today: Usage & { runs: number; costUsd: number }; d7: Usage & { runs: number; costUsd: number };
  d30: Usage & { runs: number; costUsd: number }; byModel: { model: string; tokens: number; runs: number }[];
  limits: { dailyTokens: number | null };
}
export interface FileNode { name: string; path: string; type: 'file' | 'dir'; size?: number; children?: FileNode[] }
export interface PreviewStatus { running: boolean; port: number | null; pid?: number | null; logTail?: string; url: string }
import { create } from 'zustand';
import { api } from '@/lib/api';
import type { User } from '@/lib/types';

interface AuthState {
  user: User | null;
  loading: boolean;
  refresh: () => Promise<void>;
  login: (email: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
}

export const useAuth = create<AuthState>((set) => ({
  user: null,
  loading: true,
  refresh: async () => {
    try { const { user } = await api.get<{ user: User }>('/auth/me'); set({ user, loading: false }); }
    catch { set({ user: null, loading: false }); }
  },
  login: async (email, password) => {
    const { user } = await api.post<{ user: User }>('/auth/login', { email, password });
    set({ user });
  },
  logout: async () => { await api.post('/auth/logout').catch(() => {}); set({ user: null }); },
}));

window.addEventListener('nx:unauthorized', () => useAuth.setState({ user: null }));
// Source of truth for run events + WebSocket messages. web/src/shared/protocol.ts must stay identical.

export type ModelId = string; // 'opus' | 'sonnet' | 'haiku' | full id
export type Mode = 'auto' | 'edit' | 'plan' | 'ask';
export type ThinkingLevel = 'off' | 'normal' | 'max';
export type RunStatus = 'queued' | 'running' | 'done' | 'error' | 'aborted';
export type ProjectRole = 'owner' | 'editor' | 'viewer';

export interface Usage {
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
  cacheWriteTokens: number;
}

export type RunEvent =
  | { type: 'init'; data: { sessionId: string; model: string; tools: string[]; cwd: string } }
  | { type: 'thinking'; data: { delta: string } }
  | { type: 'text'; data: { delta: string } }
  | { type: 'block_end'; data: { kind: 'thinking' | 'text' } }
  | { type: 'tool_use'; data: { id: string; name: string; input: unknown } }
  | { type: 'tool_result'; data: { id: string; isError: boolean; content: string } }
  | { type: 'todo'; data: { todos: { content: string; status: 'pending' | 'in_progress' | 'completed' }[] } }
  | { type: 'usage'; data: Usage }
  | { type: 'rate_limit'; data: Record<string, unknown> }
  | {
      type: 'result';
      data: {
        sessionId: string;
        isError: boolean;
        result: string;
        durationMs: number;
        numTurns: number;
        costUsd: number;
        usage: Usage;
      };
    }
  | { type: 'error'; data: { message: string } }
  | { type: 'done'; data: { exitCode: number | null } };

export type RunEventType = RunEvent['type'];

export interface Suggestion {
  label: string;
  prompt: string;
  kind: 'next' | 'fix' | 'test' | 'deploy' | 'explain';
}

export type FileChangeKind = 'add' | 'change' | 'unlink' | 'addDir' | 'unlinkDir';

export type ClientMsg =
  | { t: 'sub'; runId: string; fromSeq?: number }
  | { t: 'unsub'; runId: string }
  | { t: 'sub_project'; projectId: string }
  | { t: 'unsub_project'; projectId: string }
  | { t: 'ping' };

export type ServerMsg =
  | ({ t: 'run_event'; runId: string; seq: number } & RunEvent)
  | { t: 'run_status'; runId: string; conversationId: string; projectId: string; status: RunStatus }
  | { t: 'file_change'; projectId: string; path: string; kind: FileChangeKind }
  | { t: 'preview_status'; projectId: string; running: boolean; port: number | null }
  | { t: 'graph_pulse'; projectId: string; intensity: number }
  | { t: 'suggestions'; runId: string; items: Suggestion[] }
  | { t: 'pong' }
  | { t: 'error'; message: string };
