// Pure run-event reducer. No React, no DOM, no imports with side effects — unit-testable.
import type { RunEvent, RunStatus, Suggestion, Usage } from '../../shared/protocol';

export interface ThinkingBlock { kind: 'thinking'; text: string; startedAt?: number; endedAt?: number; done: boolean }
export interface TextBlock { kind: 'text'; text: string; done: boolean }
export interface ToolBlock {
  kind: 'tool'; id: string; name: string; input: any; startedAt?: number; endedAt?: number;
  result?: { isError: boolean; content: string };
}
export type Block = ThinkingBlock | TextBlock | ToolBlock;
export type Todo = { content: string; status: 'pending' | 'in_progress' | 'completed'; activeForm?: string };

export interface RunView {
  runId: string;
  status: RunStatus;
  blocks: Block[];
  todos: Todo[] | null;
  usage: Usage;
  model?: string;
  sessionId?: string;
  result?: { isError: boolean; result: string; durationMs: number; numTurns: number; costUsd: number; usage: Usage };
  error?: string;
  exitCode?: number | null;
  suggestions?: Suggestion[];
  rateLimit?: Record<string, unknown>;
  lastSeq: number;
  startedAt?: number;
  endedAt?: number;
}

export const ZERO_USAGE: Usage = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };

export function emptyRun(runId: string, status: RunStatus = 'queued', startedAt?: number): RunView {
  return { runId, status, blocks: [], todos: null, usage: { ...ZERO_USAGE }, lastSeq: -1, startedAt };
}

/** Event input: a RunEvent plus optional seq and timestamp (ts in ms; `now` used if absent). */
export type SeqEvent = RunEvent & { seq?: number; ts?: number };

const isTerminal = (s: RunStatus) => s === 'done' || s === 'error' || s === 'aborted';

/**
 * Apply one normalized run event to a RunView and return a NEW RunView (input not mutated).
 * Events with seq <= lastSeq are ignored (dedupe for replay).
 */
export function applyRunEvent(state: RunView, ev: SeqEvent, now: number = Date.now()): RunView {
  if (typeof ev.seq === 'number') {
    if (ev.seq <= state.lastSeq) return state;
  }
  const t = typeof ev.ts === 'number' ? ev.ts : now;
  const s: RunView = { ...state, blocks: state.blocks, lastSeq: typeof ev.seq === 'number' ? ev.seq : state.lastSeq };
  if (s.status === 'queued' && ev.type !== 'done') s.status = 'running';
  if (s.startedAt == null) s.startedAt = t;

  const blocks = () => (s.blocks === state.blocks ? (s.blocks = state.blocks.slice()) : s.blocks);
  const last = () => s.blocks[s.blocks.length - 1];
  const closeOpenThinking = () => {
    const b = last();
    if (b && b.kind === 'thinking' && !b.done) blocks()[s.blocks.length - 1] = { ...b, done: true, endedAt: t };
  };
  const closeOpenText = () => {
    const b = last();
    if (b && b.kind === 'text' && !b.done) blocks()[s.blocks.length - 1] = { ...b, done: true };
  };

  switch (ev.type) {
    case 'init':
      s.model = ev.data.model || s.model;
      s.sessionId = ev.data.sessionId || s.sessionId;
      break;
    case 'thinking': {
      const b = last();
      if (b && b.kind === 'thinking' && !b.done) blocks()[s.blocks.length - 1] = { ...b, text: b.text + (ev.data.delta || '') };
      else { closeOpenText(); blocks().push({ kind: 'thinking', text: ev.data.delta || '', startedAt: t, done: false }); }
      break;
    }
    case 'text': {
      const b = last();
      if (b && b.kind === 'text' && !b.done) blocks()[s.blocks.length - 1] = { ...b, text: b.text + (ev.data.delta || '') };
      else { closeOpenThinking(); blocks().push({ kind: 'text', text: ev.data.delta || '', done: false }); }
      break;
    }
    case 'block_end': {
      // close the most recent open block of that kind
      for (let i = s.blocks.length - 1; i >= 0; i--) {
        const b = s.blocks[i];
        if (b.kind === ev.data.kind && !(b as ThinkingBlock | TextBlock).done) {
          blocks()[i] = b.kind === 'thinking' ? { ...b, done: true, endedAt: t } : { ...(b as TextBlock), done: true };
          break;
        }
      }
      break;
    }
    case 'tool_use': {
      closeOpenThinking(); closeOpenText();
      const idx = s.blocks.findIndex((b) => b.kind === 'tool' && b.id === ev.data.id);
      if (idx >= 0) blocks()[idx] = { ...(s.blocks[idx] as ToolBlock), name: ev.data.name, input: ev.data.input };
      else blocks().push({ kind: 'tool', id: ev.data.id, name: ev.data.name, input: ev.data.input, startedAt: t });
      if (ev.data.name === 'TodoWrite') {
        const todos = (ev.data.input as any)?.todos;
        if (Array.isArray(todos)) s.todos = todos;
      }
      break;
    }
    case 'tool_result': {
      const idx = s.blocks.findIndex((b) => b.kind === 'tool' && b.id === ev.data.id);
      const result = { isError: !!ev.data.isError, content: String(ev.data.content ?? '') };
      if (idx >= 0) blocks()[idx] = { ...(s.blocks[idx] as ToolBlock), result, endedAt: t };
      else blocks().push({ kind: 'tool', id: ev.data.id, name: 'Tool', input: null, result, startedAt: t, endedAt: t });
      break;
    }
    case 'todo':
      s.todos = Array.isArray(ev.data.todos) ? ev.data.todos : s.todos;
      break;
    case 'usage': {
      const u = ev.data;
      s.usage = {
        inputTokens: s.usage.inputTokens + (u.inputTokens || 0),
        outputTokens: s.usage.outputTokens + (u.outputTokens || 0),
        cacheReadTokens: s.usage.cacheReadTokens + (u.cacheReadTokens || 0),
        cacheWriteTokens: s.usage.cacheWriteTokens + (u.cacheWriteTokens || 0),
      };
      break;
    }
    case 'rate_limit':
      s.rateLimit = ev.data;
      break;
    case 'result':
      closeOpenThinking(); closeOpenText();
      s.result = ev.data;
      if (ev.data.usage) s.usage = { ...ZERO_USAGE, ...ev.data.usage };
      if (ev.data.sessionId) s.sessionId = ev.data.sessionId;
      if (ev.data.isError) { s.status = 'error'; if (!s.error && ev.data.result) s.error = ev.data.result; }
      break;
    case 'error':
      s.error = ev.data.message;
      s.status = 'error';
      break;
    case 'done': {
      closeOpenThinking(); closeOpenText();
      s.exitCode = ev.data.exitCode;
      if (!isTerminal(s.status)) {
        if (s.error || s.result?.isError) s.status = 'error';
        else if (ev.data.exitCode != null && ev.data.exitCode !== 0 && !s.result) s.status = 'aborted';
        else s.status = 'done';
      }
      s.endedAt = t;
      // mark any dangling tools as finished (no result)
      s.blocks.forEach((b, i) => { if (b.kind === 'tool' && !b.endedAt) blocks()[i] = { ...b, endedAt: t }; });
      break;
    }
  }
  return s;
}

/** Fold a list of stored events into a RunView. */
export function replay(runId: string, events: SeqEvent[], base?: RunView): RunView {
  let s = base ?? emptyRun(runId, 'running');
  const sorted = events.slice().sort((a, b) => (a.seq ?? 0) - (b.seq ?? 0));
  for (const e of sorted) s = applyRunEvent(s, e, e.ts ?? s.startedAt ?? 0);
  return s;
}

export function setStatus(state: RunView, status: RunStatus, now = Date.now()): RunView {
  if (state.status === status) return state;
  const s = { ...state, status };
  if (isTerminal(status)) {
    s.endedAt = s.endedAt ?? now;
    s.blocks = s.blocks.map((b) => (b.kind !== 'tool' && !b.done ? { ...b, done: true } : b));
  }
  return s;
}

