const SUGG_RE = /<nx-suggestions>[\s\S]*?(<\/nx-suggestions>|$)/g;
/** Strip the suggestions block (even half-streamed) from displayed text. */
export function cleanText(text: string): string {
  let t = text.replace(SUGG_RE, '');
