    if (b.kind === 'tool') {
      const prev = out[out.length - 1];
      if (prev && prev.kind === 'tools') prev.tools.push(b);
      else out.push({ kind: 'tools', tools: [b], key: 'g' + b.id });
    } else if (b.kind === 'thinking') out.push({ kind: 'thinking', block: b, key: 't' + i });
