// Workspace store (one active workspace at a time; reset on project change).
import { create } from 'zustand';
import { api, ApiError } from '@/lib/api';
import { live } from '@/lib/ws';
import type {
  Attachment, Conversation, FileNode, Message, ModelInfo, PreviewStatus, Project, Run, StoredEvent, UsageSummary,
} from '@/lib/types';
import type { Mode, RunStatus, ServerMsg, Suggestion, ThinkingLevel } from '@/shared/protocol';
import { applyRunEvent, changedLines, emptyRun, replay, setStatus, type RunView, type SeqEvent } from './reducer';

// ---------- types ----------
export interface ChatItem {
  key: string;
  id?: string;
  role: 'user' | 'assistant';
  content: string;
  attachments: Attachment[];
  createdAt: string;
  userName?: string;
  runId?: string | null;
  run?: Run | null;
  suggestions?: Suggestion[];
}

export interface PendingUpload {
  localId: string;
  file: File;
  name: string;
  size: number;
  mime: string;
  previewUrl?: string;
  progress: number;
  status: 'uploading' | 'done' | 'error';
  error?: string;
  result?: Attachment;
}

export interface CodeTab {
  path: string;
  content: string;      // current editor content
  saved: string;        // last known on-disk content
  loading: boolean;
  error?: string;
  binary?: boolean;
  externalContent?: string | null;  // pending external change while dirty
  deleted?: boolean;
  flashAt?: number;     // "updated by Claude" flash
  flashLines?: number[];
  saving?: boolean;
}

export type RightTab = 'preview' | 'code';
export type LeftTab = 'files' | 'chats';
export type MobileTab = 'chat' | 'files' | 'preview' | 'code';

export interface Prefs { model: string; mode: Mode; thinking: ThinkingLevel }
export interface PreviewPrefs { autoRefresh: boolean; hmr: boolean; device: 'mobile' | 'tablet' | 'full'; subPath: string }

export interface SendError { code: string; message: string; status: number; limit?: boolean }

interface State {
  project: Project | null;
  projectError: string | null;
  canEdit: boolean;
  connected: boolean;

  conversations: Conversation[];
  convLoading: boolean;
  activeConvId: string | null;
  items: ChatItem[];
  itemsLoading: boolean;
  runs: Record<string, RunView>;
  liveSuggestions: Record<string, Suggestion[]>;

  models: ModelInfo[];
  prefs: Prefs;
  draft: { text: string; nonce: number };
  uploads: PendingUpload[];
  sending: boolean;
  sendError: SendError | null;
  usage: UsageSummary | null;

  tree: FileNode[] | null;
  treeError: string | null;
  flashes: Record<string, number>;
  expanded: Record<string, boolean>;

  tabs: CodeTab[];
  activeTab: string | null;

  leftTab: LeftTab;
  rightTab: RightTab;
  mobileTab: MobileTab;
  leftCollapsed: boolean;
  rightCollapsed: boolean;

  preview: PreviewStatus | null;
  previewBusy: boolean;
  previewNonce: number;
  previewPrefs: PreviewPrefs;
  lastFileChangeAt: number;
}

interface Actions {
  init(slug: string): Promise<void>;
  reset(): void;
  setConnected(c: boolean): void;
  loadConversations(): Promise<void>;
  selectConversation(id: string | null): Promise<void>;
  newConversation(): void;
  renameConversation(id: string, title: string): Promise<void>;
  deleteConversation(id: string): Promise<void>;
  loadMessages(convId: string, silent?: boolean): Promise<void>;
  send(text: string): Promise<boolean>;
  abort(runId?: string): Promise<void>;
  retry(runId: string): void;
  handleServerMsg(msg: ServerMsg): void;
  setPrefs(p: Partial<Prefs>): void;
  setDraft(text: string): void;
  addFiles(files: File[]): void;
  removeUpload(localId: string): void;
  clearSendError(): void;
  refreshUsage(): Promise<void>;

  refreshTree(): Promise<void>;
  toggleDir(path: string, open?: boolean): void;
  openFile(path: string): Promise<void>;
  closeTab(path: string): void;
  setTabContent(path: string, content: string): void;
  saveTab(path?: string): Promise<void>;
  reloadTab(path: string): void;
  keepMine(path: string): void;
  createFile(path: string): Promise<void>;
  createDir(path: string): Promise<void>;
  renamePath(from: string, to: string): Promise<void>;
  deletePath(path: string): Promise<void>;

  set<K extends keyof State>(k: K, v: State[K]): void;
  setRightTab(t: RightTab, reveal?: boolean): void;
  setPreviewPrefs(p: Partial<PreviewPrefs>): void;
  refreshPreview(): Promise<void>;
  previewAction(a: 'start' | 'stop'): Promise<void>;
  reloadPreview(): void;
}

export type WorkspaceStore = State & Actions;

// ---------- helpers ----------
export function unwrap<T>(data: any, ...keys: string[]): T {
  if (Array.isArray(data)) return data as unknown as T;
  for (const k of keys) if (data && data[k] !== undefined) return data[k];
  return data as T;
}

const lsGet = <T,>(k: string, d: T): T => { try { const v = localStorage.getItem(k); return v ? { ...d, ...JSON.parse(v) } : d; } catch { return d; } };
const lsSet = (k: string, v: unknown) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch { /* ignore */ } };

const DEFAULT_PREFS: Prefs = { model: 'opus', mode: 'auto', thinking: 'normal' };
const DEFAULT_PREVIEW: PreviewPrefs = { autoRefresh: true, hmr: false, device: 'full', subPath: '' };
const terminal = (s?: RunStatus) => s === 'done' || s === 'error' || s === 'aborted';

const subscribed = new Set<string>();
let treeTimer: number | undefined;
let previewTimer: number | undefined;
let reconcileTimer: number | undefined;
let unsubProject: (() => void) | null = null;
const fileFetchSeq: Record<string, number> = {};

function ensureSub(runId: string, fromSeq: number) {
  if (subscribed.has(runId)) return;
  subscribed.add(runId);
  live.subRun(runId, fromSeq);
}
function dropSub(runId: string) {
  if (!subscribed.has(runId)) return;
  subscribed.delete(runId);
  live.unsubRun(runId);
}

/** Convert server messages into chat items, synthesizing assistant items for runs that have none yet. */
function toItems(msgs: Message[]): ChatItem[] {
  const out: ChatItem[] = [];
  const assistantRuns = new Set(msgs.filter((m) => m.role === 'assistant' && m.runId).map((m) => m.runId));
  for (const m of msgs) {
    out.push({
      key: m.role === 'assistant' && m.runId ? 'run:' + m.runId : m.id, id: m.id, role: m.role, content: m.content || '',
      attachments: m.attachments || [], createdAt: m.createdAt, userName: m.userName, runId: m.runId, run: m.run, suggestions: m.suggestions,
    });
    if (m.role === 'user' && m.runId && !assistantRuns.has(m.runId)) {
      out.push({ key: 'run:' + m.runId, role: 'assistant', content: '', attachments: [], createdAt: m.createdAt, runId: m.runId, run: m.run });
    }
  }
  return out;
}

function errInfo(e: unknown): SendError {
  if (e instanceof ApiError) {
    const limit = e.status === 429 || /limit|quota|budget|exceed/i.test(e.code + ' ' + e.message);
    return { code: e.code, message: e.message, status: e.status, limit };
  }
  return { code: 'error', message: (e as Error)?.message || 'Something went wrong', status: 0 };
}

function walkFiles(nodes: FileNode[] | null, fn: (n: FileNode) => void) {
  if (!nodes) return;
  for (const n of nodes) { fn(n); if (n.children) walkFiles(n.children, fn); }
}
export function treeHas(nodes: FileNode[] | null, path: string): boolean {
  let found = false; walkFiles(nodes, (n) => { if (n.path === path) found = true; }); return found;
}

const initial = (): State => ({
  project: null, projectError: null, canEdit: false, connected: live.connected,
  conversations: [], convLoading: false, activeConvId: null, items: [], itemsLoading: false, runs: {}, liveSuggestions: {},
  models: [], prefs: DEFAULT_PREFS, draft: { text: '', nonce: 0 }, uploads: [], sending: false, sendError: null, usage: null,
  tree: null, treeError: null, flashes: {}, expanded: {},
  tabs: [], activeTab: null,
  leftTab: 'files', rightTab: 'preview', mobileTab: 'chat', leftCollapsed: false, rightCollapsed: false,
  preview: null, previewBusy: false, previewNonce: 0, previewPrefs: DEFAULT_PREVIEW, lastFileChangeAt: 0,
});

// ---------- store ----------
export const useWs = create<WorkspaceStore>((set, get) => {
  const pid = () => get().project?.id;
  const patchTab = (path: string, p: Partial<CodeTab>) =>
    set((s) => ({ tabs: s.tabs.map((t) => (t.path === path ? { ...t, ...p } : t)) }));
  const putRun = (runId: string, fn: (r: RunView) => RunView) =>
    set((s) => {
      const cur = s.runs[runId] ?? emptyRun(runId, 'running');
      const next = fn(cur);
      return next === cur ? s : { runs: { ...s.runs, [runId]: next } };
    });

  const scheduleReconcile = () => {
    window.clearTimeout(reconcileTimer);
    reconcileTimer = window.setTimeout(() => {
      const c = get().activeConvId;
      if (c) get().loadMessages(c, true);
      get().loadConversations();
      get().refreshUsage();
    }, 400);
  };

  const onExternalFileChange = async (path: string, kind: string) => {
    const tab = get().tabs.find((t) => t.path === path);
    if (!tab || !pid()) return;
    if (kind === 'unlink') { patchTab(path, { deleted: true }); return; }
    const seq = (fileFetchSeq[path] = (fileFetchSeq[path] || 0) + 1);
    try {
      const res = await api.get<any>(`/projects/${pid()}/files/content?path=${encodeURIComponent(path)}`);
      if (seq !== fileFetchSeq[path]) return;
      const content: string = typeof res === 'string' ? res : res?.content ?? '';
      const t = get().tabs.find((x) => x.path === path);
      if (!t || content === t.saved) { if (t?.deleted) patchTab(path, { deleted: false }); return; }
      const dirty = t.content !== t.saved;
      if (!dirty) patchTab(path, { content, saved: content, deleted: false, flashAt: Date.now(), flashLines: changedLines(t.saved, content), externalContent: null });
      else patchTab(path, { externalContent: content, deleted: false });
    } catch { /* ignore */ }
  };

  return {
    ...initial(),

    set: (k, v) => set({ [k]: v } as any),

    reset() {
      subscribed.forEach((r) => live.unsubRun(r));
      subscribed.clear();
      unsubProject?.(); unsubProject = null;
      set(initial());
    },

    setConnected(c) {
      set({ connected: c });
    },

    async init(slug) {
      get().reset();
      try {
        const list = unwrap<Project[]>(await api.get<any>('/projects'), 'projects', 'items');
        let project = list.find((p) => p.slug === slug) || list.find((p) => p.id === slug) || null;
        if (!project) { set({ projectError: 'Project not found or you don\'t have access.' }); return; }
        try { const full = unwrap<Project>(await api.get<any>(`/projects/${project.id}`), 'project'); if (full?.id) project = { ...project, ...full }; } catch { /* list entry is enough */ }
        const canEdit = project.myRole !== 'viewer';
        const layout = lsGet(`nx:ws:ui:${project.id}`, { leftTab: 'files' as LeftTab, rightTab: 'preview' as RightTab });
        set({
          project, canEdit,
          prefs: lsGet(`nx:ws:prefs:${project.id}`, DEFAULT_PREFS),
          previewPrefs: lsGet(`nx:ws:preview:${project.id}`, DEFAULT_PREVIEW),
          leftTab: layout.leftTab, rightTab: layout.rightTab,
        });
        unsubProject = live.subProject(project.id);
        api.get<any>('/models').then((m) => {
          const models = unwrap<ModelInfo[]>(m, 'models', 'items');
          if (!Array.isArray(models)) return;
          set({ models });
          const cur = get().prefs.model;
          if (models.length && !models.some((x) => x.id === cur)) get().setPrefs({ model: models[0].id });
        }).catch(() => set({ models: [{ id: 'opus', label: 'Opus' }, { id: 'sonnet', label: 'Sonnet' }, { id: 'haiku', label: 'Haiku' }] }));
        get().refreshTree();
        get().refreshPreview();
        get().refreshUsage();
        await get().loadConversations();
        const lastConv = (() => { try { return localStorage.getItem(`nx:ws:conv:${project!.id}`); } catch { return null; } })();
        const convs = get().conversations;
        const pick = convs.find((c) => c.id === lastConv) ?? convs[0];
        if (pick) await get().selectConversation(pick.id);
      } catch (e) {
        set({ projectError: errInfo(e).message });
      }
    },

    async loadConversations() {
      const id = pid(); if (!id) return;
      set({ convLoading: !get().conversations.length });
      try {
        const list = unwrap<Conversation[]>(await api.get<any>(`/projects/${id}/conversations`), 'conversations', 'items');
        list.sort((a, b) => String(b.updatedAt || b.createdAt).localeCompare(String(a.updatedAt || a.createdAt)));
        set({ conversations: list, convLoading: false });
      } catch { set({ convLoading: false }); }
    },

    async selectConversation(id) {
      const prev = get().activeConvId;
      if (prev && prev !== id) {
        // keep running runs subscribed only for the visible conversation
        get().items.forEach((it) => it.runId && terminal(get().runs[it.runId]?.status) && dropSub(it.runId));
      }
      set({ activeConvId: id, items: [], sendError: null, mobileTab: 'chat' });
      const p = pid();
      if (p) { try { if (id) localStorage.setItem(`nx:ws:conv:${p}`, id); else localStorage.removeItem(`nx:ws:conv:${p}`); } catch { /* */ } }
      if (id) await get().loadMessages(id);
    },

    newConversation() {
      get().selectConversation(null);
      get().setDraft('');
    },

    async renameConversation(id, title) {
      set((s) => ({ conversations: s.conversations.map((c) => (c.id === id ? { ...c, title } : c)) }));
      try { await api.patch(`/conversations/${id}`, { title }); } catch { get().loadConversations(); }
    },

    async deleteConversation(id) {
      set((s) => ({ conversations: s.conversations.filter((c) => c.id !== id) }));
      if (get().activeConvId === id) get().selectConversation(get().conversations[0]?.id ?? null);
      try { await api.del(`/conversations/${id}`); } catch { get().loadConversations(); }
    },

    async loadMessages(convId, silent) {
      if (!silent) set({ itemsLoading: true });
      try {
        const msgs = unwrap<Message[]>(await api.get<any>(`/conversations/${convId}/messages`), 'messages', 'items');
        if (get().activeConvId !== convId) return;
        const items = toItems(msgs);
        const runs = { ...get().runs };
        for (const m of msgs) {
          if (!m.runId || m.role !== 'assistant') continue;
          const evs = (m.events || []) as StoredEvent[];
          const existing = runs[m.runId];
          const maxSeq = evs.reduce((a, e) => Math.max(a, e.seq), -1);
          let rv: RunView;
          if (existing && existing.lastSeq >= maxSeq) rv = existing;
          else {
            const startedAt = m.run?.startedAt ? Date.parse(m.run.startedAt) : undefined;
            rv = replay(m.runId, evs.map((e) => ({ type: e.type, data: e.data, seq: e.seq, ts: (e as any).ts }) as SeqEvent), emptyRun(m.runId, 'running', startedAt));
            if (existing) for (const k of ['suggestions'] as const) if (existing[k] && !rv[k]) rv = { ...rv, [k]: existing[k] };
          }
          if (m.run) {
            if (m.run.status && (terminal(m.run.status) || !terminal(rv.status))) rv = setStatus(rv, m.run.status, m.run.endedAt ? Date.parse(m.run.endedAt) : undefined);
            if (m.run.startedAt && !rv.startedAt) rv = { ...rv, startedAt: Date.parse(m.run.startedAt) };
            if (m.run.endedAt && terminal(rv.status)) rv = { ...rv, endedAt: Date.parse(m.run.endedAt) };
            if (!rv.model && m.run.model) rv = { ...rv, model: m.run.model };
          }
          if (m.suggestions?.length) rv = { ...rv, suggestions: m.suggestions };
          runs[m.runId] = rv;
          if (!terminal(rv.status)) ensureSub(m.runId, rv.lastSeq + 1);
        }
        // user-only run references (assistant not created yet)
        for (const it of items) if (it.runId && !runs[it.runId]) {
          const st = it.run?.status ?? 'queued';
          runs[it.runId] = emptyRun(it.runId, st, it.run?.startedAt ? Date.parse(it.run.startedAt) : undefined);
          if (!terminal(st)) ensureSub(it.runId, 0);
        }
        set({ items, runs, itemsLoading: false });
      } catch (e) {
        set({ itemsLoading: false });
        if (!silent) set({ sendError: errInfo(e) });
      }
    },

    async send(text) {
      const s = get();
      const project = s.project;
      if (!project || !s.canEdit || s.sending) return false;
      const ups = s.uploads;
      if (ups.some((u) => u.status === 'uploading')) { set({ sendError: { code: 'uploading', message: 'Wait for uploads to finish.', status: 0 } }); return false; }
      const att = ups.filter((u) => u.status === 'done' && u.result);
      if (!text.trim() && !att.length) return false;
      set({ sending: true, sendError: null });
      try {
        let convId = s.activeConvId;
        if (!convId) {
          const title = text.trim().split('\n')[0].slice(0, 60) || 'New conversation';
          const conv = unwrap<Conversation>(await api.post<any>(`/projects/${project.id}/conversations`, { title, model: s.prefs.model, mode: s.prefs.mode }), 'conversation');
          convId = conv.id;
          set((st) => ({ conversations: [conv, ...st.conversations.filter((c) => c.id !== conv.id)], activeConvId: conv.id, items: [] }));
          try { localStorage.setItem(`nx:ws:conv:${project.id}`, conv.id); } catch { /* */ }
        }
        const { prefs } = get();
        const body = { text, attachments: att.map((u) => u.result!.id), model: prefs.model, mode: prefs.mode, thinking: prefs.thinking };
        const res = await api.post<{ runId: string; messageId: string }>(`/conversations/${convId}/prompt`, body);
        const now = new Date().toISOString();
        const runId = res.runId;
        set((st) => ({
          items: [
            ...st.items,
            { key: res.messageId || 'local:' + runId, id: res.messageId, role: 'user', content: text, attachments: att.map((u) => u.result!), createdAt: now, runId },
            { key: 'run:' + runId, role: 'assistant', content: '', attachments: [], createdAt: now, runId,
              run: { id: runId, status: 'queued', model: prefs.model, mode: prefs.mode, startedAt: now, inputTokens: 0, outputTokens: 0, cacheRead: 0, cacheWrite: 0, costUsd: 0 } },
          ],
          runs: { ...st.runs, [runId]: st.runs[runId] ?? emptyRun(runId, 'queued', Date.now()) },
          uploads: [], sending: false,
        }));
        att.forEach((u) => u.previewUrl && URL.revokeObjectURL(u.previewUrl));
        ensureSub(runId, 0);
        return true;
      } catch (e) {
        set({ sending: false, sendError: errInfo(e) });
        return false;
      }
    },

    async abort(runId) {
      const id = runId ?? [...get().items].reverse().find((it) => it.runId && !terminal(get().runs[it.runId]?.status))?.runId;
      if (!id) return;
      try { await api.post(`/runs/${id}/abort`); } catch (e) { set({ sendError: errInfo(e) }); }
    },

    retry(runId) {
      const items = get().items;
      const idx = items.findIndex((i) => i.runId === runId && i.role === 'assistant');
      const user = [...items.slice(0, idx)].reverse().find((i) => i.role === 'user');
      if (user) get().send(user.content);
    },

    handleServerMsg(msg) {
      const s = get();
      switch (msg.t) {
        case 'run_event': {
          if (!subscribed.has(msg.runId) && !s.runs[msg.runId]) return;
          const { t: _t, runId, ...ev } = msg as any;
          putRun(msg.runId, (r) => applyRunEvent(r, ev as SeqEvent));
          if (msg.type === 'done') { dropSub(msg.runId); scheduleReconcile(); }
          if (msg.type === 'todo' || msg.type === 'tool_use') { /* nothing extra */ }
          break;
        }
        case 'run_status': {
          if (s.runs[msg.runId]) {
            putRun(msg.runId, (r) => (terminal(r.status) && !terminal(msg.status) ? r : setStatus(r, msg.status)));
            if (terminal(msg.status)) { dropSub(msg.runId); scheduleReconcile(); }
          } else if (msg.conversationId && msg.conversationId === s.activeConvId) {
            scheduleReconcile();
          } else if (msg.projectId === s.project?.id) {
            window.clearTimeout(reconcileTimer);
            reconcileTimer = window.setTimeout(() => get().loadConversations(), 500);
          }
          break;
        }
        case 'suggestions': {
          set((st) => ({ liveSuggestions: { ...st.liveSuggestions, [msg.runId]: msg.items } }));
          if (s.runs[msg.runId]) putRun(msg.runId, (r) => ({ ...r, suggestions: msg.items }));
          break;
        }
        case 'file_change': {
          if (msg.projectId !== s.project?.id) return;
          const path = msg.path.replace(/^\.?\//, '');
          if (msg.kind === 'add' || msg.kind === 'change' || msg.kind === 'addDir') {
            set((st) => ({ flashes: { ...st.flashes, [path]: Date.now() } }));
            window.setTimeout(() => set((st) => {
              const f = { ...st.flashes }; if (f[path] && Date.now() - f[path] >= 1900) delete f[path]; return { flashes: f };
            }), 2000);
          }
          set({ lastFileChangeAt: Date.now() });
          window.clearTimeout(treeTimer);
          treeTimer = window.setTimeout(() => get().refreshTree(), 250);
          if (msg.kind === 'change' || msg.kind === 'add' || msg.kind === 'unlink') onExternalFileChange(path, msg.kind);
          const pp = get().previewPrefs;
          if (pp.autoRefresh && !pp.hmr && get().preview?.running) {
            window.clearTimeout(previewTimer);
            previewTimer = window.setTimeout(() => get().reloadPreview(), 600);
          }
          break;
        }
        case 'preview_status': {
          if (msg.projectId !== s.project?.id) return;
          set((st) => ({ preview: { ...(st.preview ?? { url: `/preview/${st.project!.slug}/` }), running: msg.running, port: msg.port } as PreviewStatus }));
          break;
        }
      }
    },

    setPrefs(p) {
      const prefs = { ...get().prefs, ...p };
      set({ prefs });
      const id = pid(); if (id) lsSet(`nx:ws:prefs:${id}`, prefs);
    },

    setDraft(text) { set((s) => ({ draft: { text, nonce: s.draft.nonce + 1 } })); },

    addFiles(files) {
      const project = get().project;
      if (!project || !get().canEdit) return;
      for (const file of files) {
        const localId = Math.random().toString(36).slice(2);
        const isImg = file.type.startsWith('image/');
        const up: PendingUpload = {
          localId, file, name: file.name || 'pasted-file', size: file.size, mime: file.type, progress: 0, status: 'uploading',
          previewUrl: isImg ? URL.createObjectURL(file) : undefined,
        };
        set((s) => ({ uploads: [...s.uploads, up] }));
        const form = new FormData();
        form.append('projectId', project.id);
        form.append('file', file, up.name);
        const patch = (p: Partial<PendingUpload>) => set((s) => ({ uploads: s.uploads.map((u) => (u.localId === localId ? { ...u, ...p } : u)) }));
        api.upload<Attachment>('/uploads', form, (f) => patch({ progress: f }))
          .then((r) => patch({ status: 'done', progress: 1, result: unwrap<Attachment>(r, 'upload') }))
          .catch((e) => patch({ status: 'error', error: errInfo(e).message }));
      }
    },

    removeUpload(localId) {
      set((s) => {
        const u = s.uploads.find((x) => x.localId === localId);
        if (u?.previewUrl) URL.revokeObjectURL(u.previewUrl);
        return { uploads: s.uploads.filter((x) => x.localId !== localId) };
      });
    },

    clearSendError() { set({ sendError: null }); },

    async refreshUsage() {
      try { set({ usage: await api.get<UsageSummary>('/usage/me') }); } catch { /* optional */ }
    },

    // ---- files ----
    async refreshTree() {
      const id = pid(); if (!id) return;
      try {
        const data = await api.get<any>(`/projects/${id}/files/tree`);
        let tree: FileNode[];
        if (Array.isArray(data)) tree = data;
        else if (data?.tree) tree = Array.isArray(data.tree) ? data.tree : data.tree.children ?? [];
        else if (data?.children) tree = data.children;
        else tree = [];
        set({ tree, treeError: null });
      } catch (e) { set({ treeError: errInfo(e).message }); }
    },

    toggleDir(path, open) {
      set((s) => ({ expanded: { ...s.expanded, [path]: open ?? !s.expanded[path] } }));
    },

    async openFile(path) {
      path = path.replace(/^\.?\//, '');
      const id = pid(); if (!id) return;
      get().setRightTab('code', true);
      set({ mobileTab: 'code' });
      if (get().tabs.some((t) => t.path === path)) { set({ activeTab: path }); return; }
      set((s) => ({ tabs: [...s.tabs, { path, content: '', saved: '', loading: true }], activeTab: path }));
      try {
        const res = await api.get<any>(`/projects/${id}/files/content?path=${encodeURIComponent(path)}`);
        const content: string = typeof res === 'string' ? res : res?.content ?? '';
        patchTab(path, { content, saved: content, loading: false, binary: !!res?.binary });
      } catch (e) { patchTab(path, { loading: false, error: errInfo(e).message }); }
    },

    closeTab(path) {
      set((s) => {
        const idx = s.tabs.findIndex((t) => t.path === path);
        const tabs = s.tabs.filter((t) => t.path !== path);
        const activeTab = s.activeTab === path ? (tabs[idx] ?? tabs[idx - 1])?.path ?? null : s.activeTab;
        return { tabs, activeTab };
      });
    },

    setTabContent(path, content) { patchTab(path, { content }); },

    async saveTab(path) {
      const p = path ?? get().activeTab; const id = pid();
      const tab = get().tabs.find((t) => t.path === p);
      if (!tab || !id || !get().canEdit || tab.content === tab.saved) return;
      const content = tab.content;
      patchTab(tab.path, { saving: true });
      try {
        await api.put(`/projects/${id}/files/content`, { path: tab.path, content });
        patchTab(tab.path, { saved: content, saving: false, externalContent: null, deleted: false });
      } catch (e) { patchTab(tab.path, { saving: false }); set({ sendError: errInfo(e) }); }
    },

    reloadTab(path) {
      const t = get().tabs.find((x) => x.path === path);
      if (!t || t.externalContent == null) return;
      const c = t.externalContent;
      patchTab(path, { content: c, saved: c, externalContent: null, flashAt: Date.now(), flashLines: changedLines(t.content, c) });
    },

    keepMine(path) {
      const t = get().tabs.find((x) => x.path === path);
      if (!t) return;
      patchTab(path, { saved: t.externalContent ?? t.saved, externalContent: null });
    },

    async createFile(path) {
      const id = pid(); if (!id) return;
      await api.put(`/projects/${id}/files/content`, { path, content: '' });
      await get().refreshTree();
      get().openFile(path);
    },
    async createDir(path) {
      const id = pid(); if (!id) return;
      await api.post(`/projects/${id}/files/mkdir`, { path });
      get().toggleDir(path, true);
      await get().refreshTree();
    },
    async renamePath(from, to) {
      const id = pid(); if (!id) return;
      await api.post(`/projects/${id}/files/rename`, { from, to });
      set((s) => ({
        tabs: s.tabs.map((t) => (t.path === from || t.path.startsWith(from + '/') ? { ...t, path: to + t.path.slice(from.length) } : t)),
        activeTab: s.activeTab && (s.activeTab === from || s.activeTab.startsWith(from + '/')) ? to + s.activeTab.slice(from.length) : s.activeTab,
      }));
      await get().refreshTree();
    },
    async deletePath(path) {
      const id = pid(); if (!id) return;
      await api.post(`/projects/${id}/files/delete`, { path });
      get().tabs.filter((t) => t.path === path || t.path.startsWith(path + '/')).forEach((t) => get().closeTab(t.path));
      await get().refreshTree();
    },

    // ---- layout / preview ----
    setRightTab(t, reveal) {
      set({ rightTab: t, ...(reveal ? { rightCollapsed: false } : {}) });
      const id = pid(); if (id) lsSet(`nx:ws:ui:${id}`, { leftTab: get().leftTab, rightTab: t });
    },

    setPreviewPrefs(p) {
      const previewPrefs = { ...get().previewPrefs, ...p };
      set({ previewPrefs });
      const id = pid(); if (id) lsSet(`nx:ws:preview:${id}`, previewPrefs);
    },

    async refreshPreview() {
      const id = pid(); if (!id) return;
      try { set({ preview: await api.get<PreviewStatus>(`/projects/${id}/preview/status`) }); } catch { /* */ }
    },

    async previewAction(a) {
      const id = pid(); if (!id) return;
      set({ previewBusy: true });
      try {
        const r = await api.post<any>(`/projects/${id}/preview/${a}`);
        if (r && typeof r.running === 'boolean') set({ preview: { ...(get().preview ?? {}), ...r } as PreviewStatus });
        await get().refreshPreview();
        if (a === 'start') window.setTimeout(() => { get().refreshPreview(); get().reloadPreview(); }, 2500);
      } catch (e) { set({ sendError: errInfo(e) }); }
      finally { set({ previewBusy: false }); }
    },

    reloadPreview() { set((s) => ({ previewNonce: s.previewNonce + 1 })); },
  };
});

