// Small local UI primitives for the workspace (self-contained; no dependency on the shared kit).
import { cloneElement, useCallback, useEffect, useLayoutEffect, useRef, useState, type ReactElement, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import clsx from 'clsx';

// ---------- Tooltip ----------
export function Tip({ label, children, side = 'top', kbd }: { label: ReactNode; children: ReactElement<any>; side?: 'top' | 'bottom' | 'left' | 'right'; kbd?: string }) {
  const [rect, setRect] = useState<DOMRect | null>(null);
  const timer = useRef<number>();
  const show = (e: React.SyntheticEvent) => {
    const el = e.currentTarget as HTMLElement;
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setRect(el.getBoundingClientRect()), 350);
