import { memo, useState, isValidElement, type ReactNode } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import rehypeHighlight from 'rehype-highlight';
import clsx from 'clsx';
import { Check, Copy } from 'lucide-react';

function textOf(node: ReactNode): string {
  if (node == null || typeof node === 'boolean') return '';
  if (typeof node === 'string' || typeof node === 'number') return String(node);
  if (Array.isArray(node)) return node.map(textOf).join('');
  if (isValidElement(node)) return textOf((node.props as any).children);
  return '';
}

export function CopyBtn({ text, className, label = 'Copy' }: { text: string; className?: string; label?: string }) {
  const [ok, setOk] = useState(false);
  return (
    <button
      type="button"
      onClick={() => {
        const done = () => { setOk(true); window.setTimeout(() => setOk(false), 1200); };
        if (navigator.clipboard?.writeText) navigator.clipboard.writeText(text).then(done, () => fallbackCopy(text, done));
        else fallbackCopy(text, done);
      }}
      className={clsx('inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-[11px] text-muted transition-colors hover:bg-white/5 hover:text-ink', className)}
    >
      {ok ? <Check size={12} className="text-ok" /> : <Copy size={12} />}
      {label && <span>{ok ? 'Copied' : label}</span>}
    </button>
  );
}
function fallbackCopy(text: string, done: () => void) {
  const ta = document.createElement('textarea'); ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
  document.body.appendChild(ta); ta.select();
  try { document.execCommand('copy'); done(); } catch { /* */ }
  ta.remove();
}

const PATHISH = /^[\w@.\-/]+\.[a-z0-9]{1,8}$/i;

export const Markdown = memo(function Markdown({ text, streaming, onOpenPath, isPath }: {
  text: string; streaming?: boolean; onOpenPath?: (p: string) => void; isPath?: (p: string) => boolean;
}) {
  return (
    <div className={clsx('nxw-md', streaming && 'nxw-streaming')}>
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        rehypePlugins={[[rehypeHighlight, { detect: false, ignoreMissing: true } as any]]}
        components={{
          pre({ children }) {
            const child = Array.isArray(children) ? children[0] : children;
