import { memo, useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import clsx from 'clsx';
import {
  Bot, Brain, ChevronRight, CircleCheck, Circle, CircleDot, FilePen, FileText, Globe, Link2, ListChecks, Map as MapIcon,
  NotebookPen, RotateCw, Search, SquarePen, Terminal, TriangleAlert, Wrench, FolderTree, Sparkles,
  ArrowRight, Bug, FlaskConical, Rocket, BookOpen, Square,
} from 'lucide-react';
import type { Suggestion } from '@/shared/protocol';
import { cleanText, segments, splitFinal, translateThinking, type RunView, type ThinkingBlock, type Todo, type ToolBlock } from './reducer';
import { describeTool, fmtCost, fmtDuration, fmtTokens, summarizeTools, type ToolIcon } from './toolFormat';
import { Markdown, CopyBtn } from './Markdown';
import { Spin, Tip } from './ui';
import { useWs, treeHas, isTerminal } from './store';

export function useNow(active: boolean, ms = 1000) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    if (!active) return;
    const id = window.setInterval(() => setNow(Date.now()), ms);
    return () => window.clearInterval(id);
  }, [active, ms]);
  return now;
}

const ICONS: Record<ToolIcon, typeof Bot> = {
  read: FileText, edit: SquarePen, write: FilePen, bash: Terminal, search: Search, web: Globe, fetch: Link2,
  todo: ListChecks, agent: Bot, list: FolderTree, notebook: NotebookPen, plan: MapIcon, tool: Wrench,
};

// ---------- Thinking ----------
function ThinkingLane({ block, live }: { block: ThinkingBlock; live: boolean }) {
  const streaming = live && !block.done;
  const [open, setOpen] = useState(streaming);
  const touched = useRef(false);
  const bodyRef = useRef<HTMLDivElement>(null);
  useEffect(() => { if (block.done && !touched.current) setOpen(false); }, [block.done]);
  useEffect(() => { if (streaming && open && bodyRef.current) bodyRef.current.scrollTop = bodyRef.current.scrollHeight; }, [block.text, streaming, open]);
  const now = useNow(streaming);
  const translation = useMemo(() => translateThinking(block.text), [block.text]);
  const dur = block.startedAt != null ? ((block.endedAt ?? (streaming ? now : undefined)) ?? block.startedAt) - block.startedAt : null;
  const label = streaming ? 'Thinking' : dur != null && dur > 500 ? `Thought for ${fmtDuration(dur)}` : 'Thought';
  if (!block.text.trim() && !streaming) return null;
  return (
    <div className="nxw-fade-in">
      <button
        type="button"
        onClick={() => { touched.current = true; setOpen((o) => !o); }}
        className="group flex w-full min-w-0 items-center gap-2 rounded-md py-1 text-left text-[13px] text-muted transition-colors hover:text-ink"
      >
        <Brain size={14} className={clsx('shrink-0', streaming ? 'text-violet nxw-breathe' : 'text-muted/70')} />
        <span className={clsx('shrink-0 font-medium', streaming && 'nxw-shimmer')}>{label}{streaming && dur != null && dur > 1500 ? ` · ${fmtDuration(dur)}` : ''}</span>
        {translation && <span className="min-w-0 truncate text-muted/70">— {translation}</span>}
        <ChevronRight size={13} className={clsx('ml-auto shrink-0 opacity-50 transition-transform', open && 'rotate-90')} />
      </button>
      <div className={clsx('grid transition-[grid-template-rows] duration-300 ease-out', open ? 'grid-rows-[1fr]' : 'grid-rows-[0fr]')}>
        <div className="overflow-hidden">
          <div ref={bodyRef} className="nxw-thinking ml-[6px] mt-1 max-h-72 overflow-y-auto border-l border-violet/25 pl-4 pr-2 text-[12.5px] italic leading-relaxed text-muted/80 whitespace-pre-wrap">
            {block.text}
            {streaming && <span className="nxw-caret" />}
          </div>
        </div>
      </div>
    </div>
  );
}

// ---------- Tools ----------
function ResultBox({ text, error }: { text: string; error?: boolean }) {
  const t = text.length > 6000 ? text.slice(0, 6000) + '\n… (truncated)' : text;
  if (!t.trim()) return <div className="px-3 py-2 text-xs italic text-muted">(no output)</div>;
  return (
    <pre className={clsx('max-h-72 overflow-auto px-3 py-2 font-mono text-[11.5px] leading-relaxed whitespace-pre-wrap break-words', error ? 'text-bad' : 'text-ink/80')}>{t}</pre>
  );
}

function DiffBox({ oldS, newS }: { oldS: string; newS: string }) {
  const o = oldS ? oldS.split('\n') : []; const n = newS ? newS.split('\n') : [];
  return (
    <pre className="max-h-72 overflow-auto py-1.5 font-mono text-[11.5px] leading-relaxed">
      {o.map((l, i) => <div key={'o' + i} className="bg-bad/[.08] px-3 text-bad/90"><span className="mr-2 select-none opacity-60">-</span>{l || ' '}</div>)}
      {n.map((l, i) => <div key={'n' + i} className="bg-ok/[.07] px-3 text-ok/90"><span className="mr-2 select-none opacity-60">+</span>{l || ' '}</div>)}
    </pre>
  );
}

function TodoList({ todos, compact }: { todos: Todo[]; compact?: boolean }) {
  return (
    <ul className={clsx('space-y-1', compact ? 'px-3 py-2' : '')}>
      {todos.map((t, i) => (
        <li key={i} className="flex items-start gap-2 text-[13px]">
          {t.status === 'completed' ? <CircleCheck size={14} className="mt-[3px] shrink-0 text-ok" />
            : t.status === 'in_progress' ? <CircleDot size={14} className="mt-[3px] shrink-0 text-pink nxw-breathe" />
            : <Circle size={14} className="mt-[3px] shrink-0 text-muted/50" />}
          <span className={clsx(t.status === 'completed' ? 'text-muted line-through decoration-muted/40' : t.status === 'in_progress' ? 'text-ink' : 'text-ink/75')}>
            {t.status === 'in_progress' && t.activeForm ? t.activeForm : t.content}
          </span>
        </li>
      ))}
    </ul>
  );
}

function ToolDetails({ tool }: { tool: ToolBlock }) {
  const i = tool.input || {};
  const parts: ReactNode[] = [];
  if (tool.name === 'Edit') parts.push(<DiffBox key="d" oldS={String(i.old_string ?? '')} newS={String(i.new_string ?? '')} />);
  else if (tool.name === 'MultiEdit' && Array.isArray(i.edits)) parts.push(...i.edits.map((e: any, k: number) => <DiffBox key={k} oldS={String(e.old_string ?? '')} newS={String(e.new_string ?? '')} />));
  else if (tool.name === 'Write') parts.push(<DiffBox key="w" oldS="" newS={String(i.content ?? '').split('\n').slice(0, 60).join('\n')} />);
  else if (tool.name === 'Bash') parts.push(<pre key="c" className="overflow-x-auto px-3 pt-2 font-mono text-[11.5px] text-hot/90"><span className="select-none text-muted">$ </span>{String(i.command ?? '')}</pre>);
  else if (tool.name === 'TodoWrite' && Array.isArray(i.todos)) parts.push(<TodoList key="t" todos={i.todos} compact />);
  else if (tool.name === 'Task' || tool.name === 'Agent') parts.push(<div key="p" className="px-3 pt-2 text-[12px] text-muted whitespace-pre-wrap">{String(i.prompt ?? '').slice(0, 1500)}</div>);
  const showResult = tool.result && !(tool.name === 'TodoWrite' && !tool.result.isError) && !((tool.name === 'Edit' || tool.name === 'Write' || tool.name === 'MultiEdit') && !tool.result.isError);
  if (showResult) parts.push(<ResultBox key="r" text={tool.result!.content} error={tool.result!.isError} />);
  if (!parts.length && !tool.result) parts.push(<pre key="in" className="overflow-auto px-3 py-2 font-mono text-[11px] text-muted">{JSON.stringify(tool.input, null, 2)}</pre>);
  return <div className="mt-1 overflow-hidden rounded-lg border border-line bg-bg/70">{parts}</div>;
}

function PathLink({ path, children }: { path: string; children: ReactNode }) {
  const openFile = useWs((s) => s.openFile);
  return (
    <button type="button" onClick={(e) => { e.stopPropagation(); openFile(path); }}
      className="min-w-0 truncate font-mono text-[12px] text-hot/90 underline-offset-2 hover:text-hot hover:underline">
      {children}
    </button>
  );
}

function ToolRow({ tool, live }: { tool: ToolBlock; live: boolean }) {
  const [open, setOpen] = useState(false);
  const d = describeTool(tool.name, tool.input);
  const Icon = ICONS[d.icon];
  const pending = !tool.result && !tool.endedAt && live;
  const err = tool.result?.isError;
  return (
    <div className="nxw-fade-in">
      <div
        role="button" tabIndex={0} onClick={() => setOpen((o) => !o)} onKeyDown={(e) => e.key === 'Enter' && setOpen((o) => !o)}
        className={clsx('group flex min-w-0 cursor-pointer items-center gap-2 rounded-md px-1.5 py-[3px] text-[13px] transition-colors hover:bg-white/[.03]', err ? 'text-bad' : 'text-ink/85')}
      >
        <span className="relative flex h-5 w-5 shrink-0 items-center justify-center">
          {pending ? <Spin className="h-3 w-3" /> : <Icon size={14} className={clsx(err ? 'text-bad' : 'text-pink/70')} />}
        </span>
        <span className={clsx('shrink-0', pending && 'nxw-shimmer')}>{d.verb}</span>
        {d.target && (d.targetKind === 'path' && d.path
          ? <PathLink path={d.path}>{d.target}</PathLink>
          : d.targetKind === 'code'
            ? <code className="min-w-0 truncate rounded bg-white/[.04] px-1.5 py-px font-mono text-[12px] text-hot/90">{d.target}</code>
            : <span className={clsx('min-w-0 truncate', d.targetKind === 'query' ? 'text-warm/90' : 'text-ink')}>{d.targetKind === 'query' ? `“${d.target}”` : d.target}</span>)}
        {d.stats && (d.stats.add > 0 || d.stats.del > 0) && (
          <span className="shrink-0 font-mono text-[11px]"><span className="text-ok">+{d.stats.add}</span> <span className="text-bad">-{d.stats.del}</span></span>
        )}
        {d.detail && <span className="hidden min-w-0 truncate text-[12px] text-muted/70 sm:inline">{d.detail}</span>}
        {err && <TriangleAlert size={13} className="shrink-0 text-bad" />}
        <ChevronRight size={12} className={clsx('ml-auto shrink-0 text-muted/50 opacity-0 transition group-hover:opacity-100', open && 'rotate-90 opacity-100')} />
      </div>
      {open && <div className="ml-7"><ToolDetails tool={tool} /></div>}
    </div>
  );
}

function ReadGroup({ tools, live }: { tools: ToolBlock[]; live: boolean }) {
  const [open, setOpen] = useState(false);
  const pending = live && tools.some((t) => !t.result && !t.endedAt);
  const errs = tools.filter((t) => t.result?.isError).length;
  return (
    <div className="nxw-fade-in">
      <div role="button" tabIndex={0} onClick={() => setOpen((o) => !o)} className="group flex min-w-0 cursor-pointer items-center gap-2 rounded-md px-1.5 py-[3px] text-[13px] text-ink/85 hover:bg-white/[.03]">
        <span className="flex h-5 w-5 shrink-0 items-center justify-center">{pending ? <Spin className="h-3 w-3" /> : <FileText size={14} className="text-pink/70" />}</span>
        <span className={clsx('shrink-0', pending && 'nxw-shimmer')}>Reading {tools.length} files</span>
        <span className="min-w-0 truncate font-mono text-[12px] text-muted/70">
          {tools.map((t) => describeTool(t.name, t.input).target?.split('/').pop()).join(', ')}
        </span>
        {errs > 0 && <TriangleAlert size={13} className="shrink-0 text-bad" />}
        <ChevronRight size={12} className={clsx('ml-auto shrink-0 text-muted/50 transition', open && 'rotate-90')} />
      </div>
      {open && <div className="ml-4 border-l border-line pl-2">{tools.map((t) => <ToolRow key={t.id} tool={t} live={live} />)}</div>}
    </div>
  );
}

function ActivityGroup({ tools, live }: { tools: ToolBlock[]; live: boolean }) {
  // group consecutive reads
  const rows: (ToolBlock | ToolBlock[])[] = [];
  for (const t of tools) {
    const prev = rows[rows.length - 1];
    if (t.name === 'Read') {
      if (Array.isArray(prev)) prev.push(t);
      else if (prev && !Array.isArray(prev) && prev.name === 'Read') rows[rows.length - 1] = [prev, t];
      else rows.push(t);
    } else rows.push(t);
  }
  return (
    <div className="relative my-1 space-y-px">
      {rows.map((r) => Array.isArray(r) ? <ReadGroup key={r[0].id} tools={r} live={live} /> : <ToolRow key={r.id} tool={r} live={live} />)}
    </div>
  );
}

// ---------- Todo card ----------
function TodoCard({ todos }: { todos: Todo[] }) {
  const done = todos.filter((t) => t.status === 'completed').length;
  return (
    <div className="nxw-fade-in mb-3 rounded-xl border border-pink/20 bg-gradient-to-b from-pink/[.06] to-transparent p-3 shadow-[0_0_24px_-10px_rgba(255,62,138,.4)]">
      <div className="mb-2 flex items-center gap-2 text-[12px] font-medium uppercase tracking-[.12em] text-pink/90">
        <ListChecks size={14} /> Plan
        <span className="ml-auto font-mono normal-case tracking-normal text-muted">{done}/{todos.length}</span>
      </div>
      <div className="mb-2.5 h-[3px] overflow-hidden rounded-full bg-white/5">
        <div className="h-full rounded-full bg-gradient-to-r from-pink to-warm transition-all duration-500" style={{ width: `${(done / Math.max(1, todos.length)) * 100}%` }} />
      </div>
      <TodoList todos={todos} />
    </div>
  );
}

// ---------- Suggestions ----------
const SUG_ICON: Record<Suggestion['kind'], typeof Bot> = { next: ArrowRight, fix: Bug, test: FlaskConical, deploy: Rocket, explain: BookOpen };
export function SuggestionChips({ items, disabled }: { items: Suggestion[]; disabled?: boolean }) {
  const send = useWs((s) => s.send);
  const setDraft = useWs((s) => s.setDraft);
  if (!items?.length) return null;
  return (
    <div className="mt-3 flex flex-wrap gap-2">
      {items.map((s, i) => {
        const Icon = SUG_ICON[s.kind] ?? Sparkles;
        return (
          <Tip key={i} label={<span><span className="text-muted">Click to send · Alt/Shift-click to edit</span><br />{s.prompt.slice(0, 200)}</span>}>
            <button
              type="button" disabled={disabled}
              onClick={(e) => { if (e.altKey || e.shiftKey) setDraft(s.prompt); else send(s.prompt); }}
              style={{ animationDelay: `${i * 60}ms` }}
              className="nxw-fade-in group inline-flex items-center gap-1.5 rounded-full border border-line bg-panel2/60 px-3 py-1.5 text-[12.5px] text-ink/90 transition-all hover:-translate-y-px hover:border-pink/50 hover:bg-pink/10 hover:text-ink hover:shadow-[0_0_18px_-4px_rgba(255,62,138,.5)] disabled:pointer-events-none disabled:opacity-40"
            >
              <Icon size={13} className={clsx(s.kind === 'fix' ? 'text-bad' : s.kind === 'deploy' ? 'text-warm' : s.kind === 'test' ? 'text-ok' : s.kind === 'explain' ? 'text-violet' : 'text-pink')} />
              {s.label}
            </button>
          </Tip>
        );
      })}
    </div>
  );
}

// ---------- Footer ----------
function Footer({ run, model, finalText, onRetry }: { run: RunView; model?: string; finalText: string; onRetry?: () => void }) {
  const live = !isTerminal(run.status);
  const now = useNow(live);
  const dur = run.result?.durationMs ?? (run.startedAt ? (run.endedAt ?? now) - run.startedAt : null);
  const u = run.usage;
  const statusEl = run.status === 'done' ? <span className="text-ok/80">done</span>
    : run.status === 'error' ? <span className="text-bad">error</span>
    : run.status === 'aborted' ? <span className="text-warn">stopped</span>
    : run.status === 'queued' ? <span className="text-muted">queued</span>
    : <span className="nxw-shimmer text-pink">working</span>;
  return (
    <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 font-mono text-[11px] text-muted/70">
      {(run.model || model) && <span>{(run.model || model)!.replace(/^claude-/, '')}</span>}
      {dur != null && dur > 0 && <span>{fmtDuration(dur)}</span>}
      {(u.inputTokens > 0 || u.outputTokens > 0) && (
        <Tip label={`in ${u.inputTokens.toLocaleString()} · out ${u.outputTokens.toLocaleString()} · cache read ${u.cacheReadTokens.toLocaleString()} · cache write ${u.cacheWriteTokens.toLocaleString()}`}>
          <span>↑{fmtTokens(u.inputTokens + u.cacheReadTokens + u.cacheWriteTokens)} ↓{fmtTokens(u.outputTokens)}</span>
        </Tip>
      )}
      {run.result?.costUsd != null && <span>{fmtCost(run.result.costUsd)}</span>}
      {statusEl}
      <span className="ml-auto flex items-center gap-1">
        {finalText && !live && <CopyBtn text={finalText} label="" className="opacity-60 hover:opacity-100" />}
        {onRetry && (run.status === 'error' || run.status === 'aborted') && (
          <button type="button" onClick={onRetry} className="inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-[11px] text-muted hover:bg-white/5 hover:text-ink">
            <RotateCw size={11} /> Retry
          </button>
        )}
      </span>
    </div>
  );
}

// ---------- Main ----------
export const AssistantMessage = memo(function AssistantMessage({ run, fallbackText, model, suggestions, isLast, canEdit, onRetry }: {
  run: RunView | undefined; fallbackText: string; model?: string; suggestions?: Suggestion[]; isLast: boolean; canEdit: boolean; onRetry?: () => void;
}) {
  const live = !!run && !isTerminal(run.status);
  const tree = useWs((s) => s.tree);
  const openFile = useWs((s) => s.openFile);
  const abort = useWs((s) => s.abort);
  const { process, final } = useMemo(() => splitFinal(run?.blocks ?? []), [run?.blocks]);
  const finalText = useMemo(() => {
    const t = cleanText(final.map((b) => b.text).join('\n\n'));
    return t || (run && !live && !process.length ? cleanText(fallbackText) : t) || (!run ? cleanText(fallbackText) : '');
  }, [final, fallbackText, run, live, process.length]);
  const segs = useMemo(() => segments(process), [process]);
  const tools = useMemo(() => process.filter((b): b is ToolBlock => b.kind === 'tool'), [process]);
  const [showProcess, setShowProcess] = useState<boolean | null>(null);
  const processOpen = showProcess ?? live;
  const finalStreaming = live && final.length > 0 && !final[final.length - 1].done;
  const isPath = (p: string) => treeHas(tree, p);
  const sugg = run?.suggestions ?? suggestions;
