  const dur = run?.result?.durationMs ?? (run?.startedAt && run?.endedAt ? run.endedAt - run.startedAt : null);
  const waiting = live && !run!.blocks.length;

  return (
    <div className="group/msg relative flex gap-3">
      <div className="mt-0.5 hidden h-7 w-7 shrink-0 items-center justify-center rounded-lg border border-pink/30 bg-gradient-to-br from-pink/20 to-violet/10 shadow-[0_0_16px_-4px_rgba(255,62,138,.55)] sm:flex">
        <Sparkles size={14} className={clsx('text-hot', live && 'nxw-breathe')} />
      </div>
      <div className="min-w-0 flex-1">
        {live && run?.todos && run.todos.length > 0 && <TodoCard todos={run.todos} />}

        {waiting && (
          <div className="flex items-center gap-2 py-1 text-[13px] text-muted">
            <Spin className="h-3 w-3" /><span className="nxw-shimmer">{run!.status === 'queued' ? 'Waiting for a free slot…' : 'Spinning up Claude…'}</span>
