import { useEffect, useRef, useState } from 'react';
import clsx from 'clsx';
import { Mic, Square, X } from 'lucide-react';
import { api } from '@/lib/api';
import { IconBtn, Spin } from './ui';

type Phase = 'idle' | 'recording' | 'transcribing';
const MAX_MS = 5 * 60 * 1000;

/** Mic button with an inline recording bar (level meter + timer). Calls onText with the transcription. */
export function MicControl({ onText, onError, disabled, onPhase }: {
  onText: (t: string) => void; onError: (m: string) => void; disabled?: boolean; onPhase?: (p: Phase) => void;
}) {
  const [phase, setPhaseState] = useState<Phase>('idle');
  const [elapsed, setElapsed] = useState(0);
  const rec = useRef<MediaRecorder | null>(null);
  const chunks = useRef<Blob[]>([]);
  const cancelled = useRef(false);
  const bars = useRef<HTMLDivElement>(null);
  const cleanup = useRef<() => void>(() => {});
  const setPhase = (p: Phase) => { setPhaseState(p); onPhase?.(p); };

  useEffect(() => () => cleanup.current(), []);

  const start = async () => {
    if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder === 'undefined') { onError('Voice input is not supported in this browser.'); return; }
    let stream: MediaStream;
    try { stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } }); }
    catch { onError('Microphone permission denied.'); return; }
    const mime = ['audio/webm;codecs=opus', 'audio/webm', 'audio/ogg;codecs=opus', 'audio/mp4'].find((m) => MediaRecorder.isTypeSupported(m));
    const r = new MediaRecorder(stream, mime ? { mimeType: mime } : undefined);
    rec.current = r; chunks.current = []; cancelled.current = false;
    r.ondataavailable = (e) => e.data.size && chunks.current.push(e.data);
    const AC: typeof AudioContext = (window as any).AudioContext || (window as any).webkitAudioContext;
    const ctx = new AC();
    const src = ctx.createMediaStreamSource(stream);
    const an = ctx.createAnalyser(); an.fftSize = 256; an.smoothingTimeConstant = 0.6;
    src.connect(an);
    const buf = new Uint8Array(an.frequencyBinCount);
    let raf = 0; const t0 = Date.now();
    const hist: number[] = Array(28).fill(0);
    const tick = () => {
      an.getByteTimeDomainData(buf);
      let sum = 0; for (let i = 0; i < buf.length; i++) { const v = (buf[i] - 128) / 128; sum += v * v; }
      const level = Math.min(1, Math.sqrt(sum / buf.length) * 3.2);
      hist.push(level); hist.shift();
      const el = bars.current;
      if (el) for (let i = 0; i < el.children.length; i++) (el.children[i] as HTMLElement).style.transform = `scaleY(${0.12 + hist[i] * 0.88})`;
      const ms = Date.now() - t0;
      setElapsed(ms);
      if (ms > MAX_MS) { stop(); return; }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    cleanup.current = () => {
      cancelAnimationFrame(raf);
      stream.getTracks().forEach((t) => t.stop());
      ctx.close().catch(() => {});
      if (rec.current && rec.current.state !== 'inactive') { cancelled.current = true; rec.current.stop(); }
    };
    r.onstop = async () => {
      cancelAnimationFrame(raf);
      stream.getTracks().forEach((t) => t.stop());
      ctx.close().catch(() => {});
      if (cancelled.current) { setPhase('idle'); return; }
      const blob = new Blob(chunks.current, { type: r.mimeType || 'audio/webm' });
      if (blob.size < 800) { setPhase('idle'); return; }
      setPhase('transcribing');
      try {
        const form = new FormData();
        const ext = (r.mimeType || '').includes('ogg') ? 'ogg' : (r.mimeType || '').includes('mp4') ? 'm4a' : 'webm';
        form.append('audio', blob, `recording.${ext}`);
        const res = await api.upload<{ text: string }>('/transcribe', form);
        const text = (res?.text || '').trim();
        if (text) onText(text); else onError('No speech detected.');
