import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import clsx from 'clsx';
import {
  ArrowUp, Brain, Check, ChevronDown, Cpu, FileText, Map as MapIcon, MessageCircleQuestionMark, Paperclip, Square,
  SquarePen, TriangleAlert, X, Zap, Eye, Gauge,
} from 'lucide-react';
import type { Mode, ThinkingLevel } from '@/shared/protocol';
import { useWs, isTerminal } from './store';
import { MicControl } from './Mic';
import { IconBtn, MenuItem, Popover, Tip, modKey } from './ui';
import { fmtBytes } from './toolFormat';

export const MODES: { id: Mode; label: string; icon: typeof Zap; desc: string }[] = [
  { id: 'auto', label: 'Auto', icon: Zap, desc: 'Full autonomy — reads, edits, runs commands and installs packages without asking.' },
  { id: 'edit', label: 'Edit', icon: SquarePen, desc: 'Edits files and runs common dev tools; file edits are auto-accepted.' },
  { id: 'plan', label: 'Plan', icon: MapIcon, desc: 'Explores the code and proposes a plan. Changes nothing.' },
  { id: 'ask', label: 'Ask', icon: MessageCircleQuestionMark, desc: 'Read-only Q&A. No writes, no shell commands.' },
];
const THINKING: { id: ThinkingLevel; label: string; desc: string }[] = [
  { id: 'off', label: 'Off', desc: 'Fastest. No extended thinking.' },
  { id: 'normal', label: 'Normal', desc: 'Balanced reasoning budget.' },
  { id: 'max', label: 'Max', desc: 'Deep reasoning for hard problems. Slower.' },
];

interface Cmd { name: string; args?: string; desc: string }
const COMMANDS: Cmd[] = [
  { name: 'new', desc: 'Start a new conversation' },
  { name: 'clear', desc: 'Clear context — fresh conversation' },
  { name: 'model', args: '<model>', desc: 'Switch model' },
  { name: 'mode', args: '<auto|edit|plan|ask>', desc: 'Switch mode' },
  { name: 'preview', desc: 'Show the live preview' },
  { name: 'files', desc: 'Show the file explorer' },
];

function Pill({ children, onClick, active, innerRef, label }: { children: React.ReactNode; onClick: () => void; active?: boolean; innerRef?: (el: HTMLButtonElement | null) => void; label?: string }) {
  const b = (
    <button ref={innerRef} type="button" onClick={onClick}
      className={clsx('inline-flex h-7 items-center gap-1.5 rounded-lg px-2 text-[12px] transition-colors',
        active ? 'bg-pink/15 text-hot' : 'text-muted hover:bg-white/[.05] hover:text-ink')}>
      {children}
    </button>
  );
  return label ? <Tip label={label}>{b}</Tip> : b;
}

export function PromptBox() {
  const prefs = useWs((s) => s.prefs);
  const setPrefs = useWs((s) => s.setPrefs);
  const models = useWs((s) => s.models);
  const canEdit = useWs((s) => s.canEdit);
  const uploads = useWs((s) => s.uploads);
  const draft = useWs((s) => s.draft);
  const sending = useWs((s) => s.sending);
  const sendError = useWs((s) => s.sendError);
  const items = useWs((s) => s.items);
  const runs = useWs((s) => s.runs);
  const usage = useWs((s) => s.usage);
  const { send, abort, addFiles, removeUpload, newConversation, clearSendError, setRightTab, set } = useWs.getState();

  const [text, setText] = useState('');
  const [focused, setFocused] = useState(false);
  const [menu, setMenu] = useState<null | 'mode' | 'model' | 'thinking'>(null);
  const [anchors] = useState<Record<string, HTMLElement | null>>({});
  const [, force] = useState(0);
  const [micErr, setMicErr] = useState<string | null>(null);
  const [slashIdx, setSlashIdx] = useState(0);
  const [slashDismissed, setSlashDismissed] = useState(false);
  const ta = useRef<HTMLTextAreaElement>(null);
  const fileInput = useRef<HTMLInputElement>(null);

  const runningId = useMemo(() => {
    for (let i = items.length - 1; i >= 0; i--) { const r = items[i].runId && runs[items[i].runId!]; if (r && !isTerminal(r.status)) return r.runId; }
    return null;
  }, [items, runs]);

  // draft injections (suggestion alt-click, etc.)
  useEffect(() => {
    if (!draft.nonce) return;
    setText(draft.text);
    requestAnimationFrame(() => { const el = ta.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } });
  }, [draft.nonce]); // eslint-disable-line react-hooks/exhaustive-deps

  // focus shortcut from elsewhere
  useEffect(() => {
    const f = () => ta.current?.focus();
    window.addEventListener('nxw:focus-prompt', f);
    return () => window.removeEventListener('nxw:focus-prompt', f);
  }, []);

  // autosize
  useLayoutEffect(() => {
    const el = ta.current; if (!el) return;
    el.style.height = '0px';
    el.style.height = Math.min(el.scrollHeight, Math.round(window.innerHeight * 0.4)) + 'px';
  }, [text]);

  const insertAtCursor = useCallback((t: string) => {
    const el = ta.current;
    setText((cur) => {
      const s = el?.selectionStart ?? cur.length, e = el?.selectionEnd ?? cur.length;
      const pre = cur.slice(0, s), post = cur.slice(e);
      const sep = pre && !/\s$/.test(pre) ? ' ' : '';
      const next = pre + sep + t + (post && !/^\s/.test(post) ? ' ' : '') + post;
      requestAnimationFrame(() => { if (el) { const p = (pre + sep + t).length; el.focus(); el.setSelectionRange(p, p); } });
      return next;
    });
  }, []);

  // ---- slash commands ----
  const slash = useMemo(() => {
    if (slashDismissed || !text.startsWith('/')) return null;
    const m1 = /^\/(\w*)$/.exec(text);
    if (m1) {
      const q = m1[1].toLowerCase();
      const list = COMMANDS.filter((c) => c.name.startsWith(q));
      return list.length ? { kind: 'cmd' as const, list: list.map((c) => ({ key: c.name, label: '/' + c.name, hint: c.args, desc: c.desc, apply: c.args ? '/' + c.name + ' ' : '/' + c.name })) } : null;
    }
    const m2 = /^\/(model|mode)\s+(\S*)$/i.exec(text);
    if (m2) {
      const q = m2[2].toLowerCase();
      const opts = m2[1].toLowerCase() === 'model'
        ? models.map((m) => ({ key: m.id, label: m.label, desc: m.id }))
        : MODES.map((m) => ({ key: m.id, label: m.label, desc: m.desc }));
      const list = opts.filter((o) => o.key.toLowerCase().startsWith(q) || o.label.toLowerCase().startsWith(q));
      return list.length ? { kind: 'arg' as const, list: list.map((o) => ({ ...o, hint: undefined, apply: `/${m2[1].toLowerCase()} ${o.key}` })) } : null;
    }
    return null;
  }, [text, models, slashDismissed]);
  useEffect(() => { setSlashIdx(0); }, [slash?.list.length, slash?.kind]);
  useEffect(() => { if (!text.startsWith('/')) setSlashDismissed(false); }, [text]);

  const runCommand = (raw: string): boolean => {
    const m = /^\/(\w+)(?:\s+(.*))?$/.exec(raw.trim());
    if (!m) return false;
    const [, name, arg = ''] = m;
    const a = arg.trim().toLowerCase();
    switch (name.toLowerCase()) {
      case 'new': case 'clear': newConversation(); setText(''); return true;
      case 'preview': setRightTab('preview', true); set('mobileTab', 'preview'); setText(''); return true;
      case 'files': set('leftTab', 'files'); set('leftCollapsed', false); set('mobileTab', 'files'); setText(''); return true;
      case 'model': {
        const mm = models.find((x) => x.id.toLowerCase() === a || x.label.toLowerCase().includes(a));
        if (mm || a) { setPrefs({ model: mm?.id ?? arg.trim() }); setText(''); return true; }
        return false;
      }
      case 'mode': {
        const md = MODES.find((x) => x.id === a);
        if (md) { setPrefs({ mode: md.id }); setText(''); return true; }
        return false;
      }
    }
    return false;
  };

  const doSend = async () => {
    if (!canEdit || sending) return;
    const t = text;
    if (t.startsWith('/') && runCommand(t)) return;
    if (runningId) return;
    if (!t.trim() && !uploads.some((u) => u.status === 'done')) return;
    const ok = await send(t);
    if (ok) setText('');
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (slash) {
      if (e.key === 'ArrowDown') { e.preventDefault(); setSlashIdx((i) => (i + 1) % slash.list.length); return; }
      if (e.key === 'ArrowUp') { e.preventDefault(); setSlashIdx((i) => (i - 1 + slash.list.length) % slash.list.length); return; }
      if (e.key === 'Escape') { e.preventDefault(); setSlashDismissed(true); return; }
      if (e.key === 'Tab' || (e.key === 'Enter' && !e.shiftKey)) {
        const it = slash.list[slashIdx];
        if (it) {
          e.preventDefault();
          const full = it.apply;
          if (e.key === 'Enter' && (slash.kind === 'arg' || !full.endsWith(' '))) { if (!runCommand(full)) setText(full); }
          else setText(full);
          return;
        }
      }
    }
    if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) { e.preventDefault(); doSend(); }
  };

  const onPaste = (e: React.ClipboardEvent) => {
    const files = Array.from(e.clipboardData.files || []);
    if (files.length) { e.preventDefault(); addFiles(files.map((f, i) => (f.name && f.name !== 'image.png') ? f : new File([f], `pasted-${Date.now()}-${i}.${(f.type.split('/')[1] || 'bin').replace('jpeg', 'jpg')}`, { type: f.type }))); }
  };

  const mode = MODES.find((m) => m.id === prefs.mode) ?? MODES[0];
  const model = models.find((m) => m.id === prefs.model);
  const think = THINKING.find((t) => t.id === prefs.thinking) ?? THINKING[1];
  const anchor = (k: string) => (el: HTMLElement | null) => { if (anchors[k] !== el) { anchors[k] = el; force((n) => n + 1); } };
  const hasContent = !!text.trim() || uploads.some((u) => u.status === 'done');
  const limitPct = usage?.limits?.dailyTokens ? Math.min(1, ((usage.today.inputTokens || 0) + (usage.today.outputTokens || 0)) / usage.limits.dailyTokens) : null;

  if (!canEdit) {
    return (
      <div className="border-t border-line/60 px-4 py-3">
        <div className="mx-auto flex max-w-[820px] items-center justify-center gap-2 rounded-xl border border-dashed border-line px-4 py-3 text-[13px] text-muted">
          <Eye size={15} /> You have view-only access to this project.
        </div>
      </div>
    );
  }

  return (
    <div className="relative px-3 pb-3 pt-1 sm:px-5">
      <div className="mx-auto max-w-[820px]">
        {sendError && (
          <div className={clsx('nxw-fade-in mb-2 flex items-start gap-2 rounded-xl border px-3 py-2 text-[13px]',
            sendError.limit ? 'border-warn/40 bg-warn/[.07] text-warn' : 'border-bad/40 bg-bad/[.07] text-bad')}>
            {sendError.limit ? <Gauge size={15} className="mt-0.5 shrink-0" /> : <TriangleAlert size={15} className="mt-0.5 shrink-0" />}
            <div className="min-w-0 flex-1">
              {sendError.limit && <div className="font-medium">Usage limit reached</div>}
              <div className={clsx(sendError.limit && 'text-warn/80')}>{sendError.message}{sendError.limit && ' Your limit resets daily — contact an admin to raise it.'}</div>
            </div>
            <button type="button" onClick={clearSendError} className="shrink-0 opacity-70 hover:opacity-100"><X size={14} /></button>
          </div>
        )}
        {micErr && (
          <div className="nxw-fade-in mb-2 flex items-center gap-2 rounded-xl border border-warn/30 bg-warn/[.06] px-3 py-1.5 text-[12.5px] text-warn">
            <TriangleAlert size={14} /> <span className="flex-1">{micErr}</span>
            <button type="button" onClick={() => setMicErr(null)}><X size={13} /></button>
          </div>
        )}

        <div className={clsx(
          'nxw-prompt relative rounded-2xl border bg-panel/90 backdrop-blur transition-all duration-200',
          focused ? 'border-pink/50 shadow-[0_0_0_3px_rgba(255,62,138,.10),0_0_40px_-12px_rgba(255,62,138,.55)]' : 'border-line shadow-[0_10px_40px_-20px_rgba(0,0,0,.9)]',
        )}>
          {/* slash popup */}
          {slash && focused && (
            <div className="nxw-pop absolute bottom-full left-2 z-20 mb-2 w-[min(380px,calc(100%-16px))] overflow-hidden rounded-xl border border-line bg-panel/95 p-1 shadow-[0_18px_50px_rgba(0,0,0,.7)] backdrop-blur-md">
              <div className="px-2.5 pb-1 pt-1.5 text-[10.5px] uppercase tracking-[.14em] text-muted">{slash.kind === 'cmd' ? 'Commands' : 'Options'}</div>
              {slash.list.map((it, i) => (
                <button key={it.key} type="button" onMouseDown={(e) => { e.preventDefault(); if (!it.apply.endsWith(' ') && runCommand(it.apply)) return; setText(it.apply); ta.current?.focus(); }}
                  onMouseEnter={() => setSlashIdx(i)}
                  className={clsx('flex w-full items-baseline gap-2 rounded-lg px-2.5 py-1.5 text-left text-[13px]', i === slashIdx ? 'bg-pink/10 text-ink' : 'text-ink/80')}>
                  <span className={clsx('font-mono', i === slashIdx && 'text-hot')}>{it.label}</span>
                  {it.hint && <span className="font-mono text-[11px] text-muted">{it.hint}</span>}
                  <span className="ml-auto truncate text-[12px] text-muted">{it.desc}</span>
                </button>
              ))}
            </div>
          )}

          {/* attachments */}
          {uploads.length > 0 && (
            <div className="flex flex-wrap gap-2 px-3 pt-3">
              {uploads.map((u) => (
                <div key={u.localId} className={clsx('nxw-fade-in group relative overflow-hidden rounded-lg border bg-bg/60', u.status === 'error' ? 'border-bad/50' : 'border-line')}>
                  {u.previewUrl ? (
                    <img src={u.previewUrl} alt={u.name} className="h-16 w-16 object-cover" />
                  ) : (
                    <div className="flex h-16 w-44 items-center gap-2 px-2.5">
                      <FileText size={18} className="shrink-0 text-pink" />
                      <div className="min-w-0">
                        <div className="truncate text-[12px] text-ink">{u.name}</div>
                        <div className="text-[11px] text-muted">{u.status === 'error' ? <span className="text-bad">{u.error}</span> : fmtBytes(u.size)}</div>
                      </div>
                    </div>
                  )}
                  {u.status === 'uploading' && (
                    <div className="absolute inset-x-0 bottom-0 h-1 bg-black/40"><div className="h-full bg-gradient-to-r from-pink to-warm transition-all" style={{ width: `${Math.round(u.progress * 100)}%` }} /></div>
                  )}
                  {u.status === 'error' && u.previewUrl && <div className="absolute inset-0 flex items-center justify-center bg-bad/30"><TriangleAlert size={16} className="text-bad" /></div>}
                  <button type="button" onClick={() => removeUpload(u.localId)} title="Remove"
                    className="absolute right-1 top-1 flex h-5 w-5 items-center justify-center rounded-full bg-black/70 text-ink opacity-0 transition group-hover:opacity-100">
                    <X size={11} />
                  </button>
                </div>
              ))}
            </div>
          )}

          <textarea
            ref={ta} value={text} rows={1}
            onChange={(e) => { setText(e.target.value); if (sendError && !sending) clearSendError(); }}
            onKeyDown={onKeyDown} onPaste={onPaste}
            onFocus={() => setFocused(true)} onBlur={() => setFocused(false)}
            placeholder={runningId ? 'Claude is working… (type ahead, ' + modKey + '. to stop)' : 'Ask Claude to build, fix, or explain…  ( / for commands )'}
            className="nxw-scroll block max-h-[40vh] w-full resize-none bg-transparent px-4 pb-1.5 pt-3.5 text-[14.5px] leading-relaxed text-ink outline-none placeholder:text-muted/60"
          />

          <div className="flex items-center gap-1 px-2 pb-2">
            <input ref={fileInput} type="file" multiple hidden onChange={(e) => { addFiles(Array.from(e.target.files || [])); e.target.value = ''; }} />
            <IconBtn label="Attach files (or paste / drop)" onClick={() => fileInput.current?.click()}><Paperclip size={16} /></IconBtn>
            <MicControl onText={insertAtCursor} onError={(m) => { setMicErr(m); window.setTimeout(() => setMicErr(null), 5000); }} />
            <div className="mx-1 h-4 w-px bg-line" />

            <Pill innerRef={anchor('mode')} active={menu === 'mode'} onClick={() => setMenu(menu === 'mode' ? null : 'mode')} label={mode.desc}>
              <mode.icon size={14} className={clsx(prefs.mode === 'auto' ? 'text-pink' : prefs.mode === 'plan' ? 'text-violet' : prefs.mode === 'ask' ? 'text-warm' : 'text-ok')} />
              <span className="hidden sm:inline">{mode.label}</span>
              <ChevronDown size={12} className="opacity-50" />
            </Pill>
            <Pill innerRef={anchor('model')} active={menu === 'model'} onClick={() => setMenu(menu === 'model' ? null : 'model')}>
              <Cpu size={14} />
              <span className="max-w-[110px] truncate">{model?.label ?? prefs.model}</span>
              <ChevronDown size={12} className="opacity-50" />
            </Pill>
            <Pill innerRef={anchor('thinking')} active={menu === 'thinking'} onClick={() => setMenu(menu === 'thinking' ? null : 'thinking')} label={`Extended thinking: ${think.label}`}>
              <Brain size={14} className={clsx(prefs.thinking === 'max' ? 'text-violet' : prefs.thinking === 'off' ? 'opacity-50' : '')} />
              <span className="hidden md:inline">{think.label}</span>
            </Pill>

            <div className="ml-auto flex items-center gap-2">
              {limitPct != null && limitPct > 0.6 && (
                <Tip label={`${Math.round(limitPct * 100)}% of today's token budget used`}>
                  <div className="hidden h-1.5 w-14 overflow-hidden rounded-full bg-white/5 sm:block"><div className={clsx('h-full', limitPct > 0.9 ? 'bg-bad' : 'bg-warn')} style={{ width: `${limitPct * 100}%` }} /></div>
                </Tip>
              )}
              {runningId ? (
                <Tip label="Stop" kbd={`${modKey}.`}>
                  <button type="button" onClick={() => abort(runningId)}
                    className="flex h-8 w-8 items-center justify-center rounded-full border border-pink/50 bg-pink/10 text-hot transition hover:bg-pink/20 nxw-ring">
                    <Square size={11} fill="currentColor" />
                  </button>
                </Tip>
              ) : (
                <Tip label="Send" kbd="↵">
                  <button type="button" onClick={doSend} disabled={!hasContent || sending}
                    className={clsx('flex h-8 w-8 items-center justify-center rounded-full transition-all duration-200',
                      hasContent ? 'bg-gradient-to-br from-pink to-hot text-black shadow-[0_0_20px_-2px_rgba(255,62,138,.8)] hover:scale-105' : 'bg-white/[.06] text-muted')}>
                    {sending ? <span className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-black/30 border-t-black" /> : <ArrowUp size={16} strokeWidth={2.5} />}
                  </button>
                </Tip>
              )}
            </div>
          </div>
        </div>
      </div>

      <Popover open={menu === 'mode'} anchor={anchors.mode ?? null} onClose={() => setMenu(null)} className="w-[300px]">
        {MODES.map((m) => (
          <button key={m.id} type="button" onClick={() => { setPrefs({ mode: m.id }); setMenu(null); }}
            className={clsx('flex w-full items-start gap-2.5 rounded-lg px-2.5 py-2 text-left transition-colors', prefs.mode === m.id ? 'bg-pink/10' : 'hover:bg-white/5')}>
            <m.icon size={15} className={clsx('mt-0.5 shrink-0', prefs.mode === m.id ? 'text-hot' : 'text-muted')} />
            <span className="min-w-0 flex-1">
              <span className="block text-[13px] text-ink">{m.label}</span>
              <span className="block text-[11.5px] leading-snug text-muted">{m.desc}</span>
            </span>
            {prefs.mode === m.id && <Check size={14} className="mt-0.5 text-hot" />}
          </button>
        ))}
      </Popover>
      <Popover open={menu === 'model'} anchor={anchors.model ?? null} onClose={() => setMenu(null)} className="w-[220px]">
        {(models.length ? models : [{ id: prefs.model, label: prefs.model }]).map((m) => (
          <MenuItem key={m.id} active={prefs.model === m.id} icon={<Cpu size={14} />} hint={prefs.model === m.id ? <Check size={13} /> : undefined}
            onClick={() => { setPrefs({ model: m.id }); setMenu(null); }}>
            {m.label}
          </MenuItem>
        ))}
      </Popover>
      <Popover open={menu === 'thinking'} anchor={anchors.thinking ?? null} onClose={() => setMenu(null)} className="w-[250px]">
        <div className="px-2.5 pb-1 pt-1.5 text-[10.5px] uppercase tracking-[.14em] text-muted">Extended thinking</div>
        {THINKING.map((t) => (
          <button key={t.id} type="button" onClick={() => { setPrefs({ thinking: t.id }); setMenu(null); }}
            className={clsx('flex w-full items-start gap-2.5 rounded-lg px-2.5 py-1.5 text-left', prefs.thinking === t.id ? 'bg-pink/10' : 'hover:bg-white/5')}>
            <Brain size={14} className={clsx('mt-0.5', prefs.thinking === t.id ? 'text-hot' : 'text-muted')} />
            <span className="flex-1"><span className="block text-[13px] text-ink">{t.label}</span><span className="block text-[11.5px] text-muted">{t.desc}</span></span>
            {prefs.thinking === t.id && <Check size={14} className="mt-0.5 text-hot" />}
          </button>
        ))}
      </Popover>
    </div>
  );
}

