import { useEffect, useRef, useState } from 'react';
import clsx from 'clsx';
import {
  ExternalLink, Monitor, Play, Power, RotateCw, ScrollText, Smartphone, Tablet, Sparkles, Zap, ChevronDown, Globe,
} from 'lucide-react';
import { useWs } from './store';
import { Dot, IconBtn, Popover, Spin, Tip } from './ui';

const DEVICES = [
  { id: 'mobile' as const, w: 390, icon: Smartphone, label: 'Mobile · 390px' },
  { id: 'tablet' as const, w: 820, icon: Tablet, label: 'Tablet · 820px' },
  { id: 'full' as const, w: 0, icon: Monitor, label: 'Full width' },
];

export function PreviewPane() {
  const project = useWs((s) => s.project);
  const preview = useWs((s) => s.preview);
  const busy = useWs((s) => s.previewBusy);
  const nonce = useWs((s) => s.previewNonce);
  const pp = useWs((s) => s.previewPrefs);
  const canEdit = useWs((s) => s.canEdit);
  const tree = useWs((s) => s.tree);
  const { previewAction, setPreviewPrefs, reloadPreview, refreshPreview, send, setDraft } = useWs.getState();
  const [path, setPath] = useState(pp.subPath);
  const [logsOpen, setLogsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [optsEl, setOptsEl] = useState<HTMLElement | null>(null);
  const [optsOpen, setOptsOpen] = useState(false);
  const [flash, setFlash] = useState(0);
  const iframe = useRef<HTMLIFrameElement>(null);
  const base = `/preview/${project?.slug}/`;
  const src = base + pp.subPath.replace(/^\//, '');

  useEffect(() => setPath(pp.subPath), [pp.subPath]);
  useEffect(() => {
    if (!nonce) return;
    const f = iframe.current; if (!f) return;
    setLoading(true); setFlash(Date.now());
    try { f.contentWindow?.location.reload(); } catch { f.src = src; }
  }, [nonce]); // eslint-disable-line react-hooks/exhaustive-deps

  // poll logs while drawer open
  useEffect(() => {
    if (!logsOpen) return;
    refreshPreview();
    const id = window.setInterval(refreshPreview, 3000);
    return () => window.clearInterval(id);
  }, [logsOpen, refreshPreview]);

  // track in-iframe navigation (same-origin)
  const onLoad = () => {
    setLoading(false);
    try {
      const loc = iframe.current?.contentWindow?.location;
      if (loc && loc.pathname.startsWith(base)) setPath(loc.pathname.slice(base.length) + loc.search + loc.hash);
    } catch { /* cross-origin */ }
  };

  const running = !!preview?.running;
  const hasFiles = !!tree && tree.length > 0;
  const dev = DEVICES.find((d) => d.id === pp.device) ?? DEVICES[2];

  return (
    <div className="flex h-full min-h-0 flex-col">
      {/* URL bar */}
      <div className="flex h-10 shrink-0 items-center gap-1 border-b border-line/70 px-2">
        <IconBtn label="Reload" onClick={() => reloadPreview()} disabled={!running}><RotateCw size={14} className={clsx(loading && 'animate-spin')} /></IconBtn>
        <form className="flex h-7 min-w-0 flex-1 items-center rounded-lg border border-line bg-bg/70 px-2 font-mono text-[12px] focus-within:border-pink/40"
          onSubmit={(e) => { e.preventDefault(); const p = path.replace(/^\//, ''); setPreviewPrefs({ subPath: p }); if (iframe.current) iframe.current.src = base + p; }}>
          <Tip label={running ? `Running on port ${preview?.port ?? '?'}` : 'Preview stopped'}><span className="mr-2 flex"><Dot tone={running ? 'ok' : 'muted'} pulse={running && loading} /></span></Tip>
          <span className="shrink-0 text-muted/70">{base}</span>
          <input value={path} onChange={(e) => setPath(e.target.value)} spellCheck={false}
            className="min-w-0 flex-1 bg-transparent text-ink outline-none" placeholder="" />
        </form>
        <div className="hidden items-center gap-0.5 rounded-lg border border-line p-0.5 md:flex">
          {DEVICES.map((d) => (
            <IconBtn key={d.id} label={d.label} active={pp.device === d.id} onClick={() => setPreviewPrefs({ device: d.id })} className="h-6 w-6"><d.icon size={13} /></IconBtn>
          ))}
        </div>
        <IconBtn label="Preview options" innerRefFix={setOptsEl} onClick={() => setOptsOpen((o) => !o)} active={optsOpen}><ChevronDown size={14} /></IconBtn>
        <IconBtn label="Logs" active={logsOpen} onClick={() => setLogsOpen((o) => !o)}><ScrollText size={14} /></IconBtn>
        <IconBtn label="Open in new tab" onClick={() => window.open(src, '_blank', 'noopener')} disabled={!running}><ExternalLink size={14} /></IconBtn>
        {canEdit && (running ? (
          <IconBtn label="Stop preview server" onClick={() => previewAction('stop')} disabled={busy} className="hover:text-bad">{busy ? <Spin className="h-3 w-3" /> : <Power size={14} />}</IconBtn>
        ) : (
          <IconBtn label="Start preview server" onClick={() => previewAction('start')} disabled={busy} glow>{busy ? <Spin className="h-3 w-3" /> : <Play size={14} />}</IconBtn>
        ))}
      </div>

      <Popover open={optsOpen} anchor={optsEl} onClose={() => setOptsOpen(false)} side="bottom" align="end" className="w-[270px]">
        <label className="flex cursor-pointer items-start gap-2.5 rounded-lg px-2.5 py-2 hover:bg-white/5">
          <input type="checkbox" className="mt-1 accent-[var(--pink)]" checked={pp.autoRefresh} onChange={(e) => setPreviewPrefs({ autoRefresh: e.target.checked })} />
          <span><span className="block text-[13px] text-ink">Auto-refresh on file changes</span><span className="block text-[11.5px] text-muted">Reloads 600 ms after Claude edits files.</span></span>
        </label>
        <label className="flex cursor-pointer items-start gap-2.5 rounded-lg px-2.5 py-2 hover:bg-white/5">
          <input type="checkbox" className="mt-1 accent-[var(--pink)]" checked={pp.hmr} onChange={(e) => setPreviewPrefs({ hmr: e.target.checked })} />
          <span><span className="block text-[13px] text-ink">App uses hot reload (HMR)</span><span className="block text-[11.5px] text-muted">Skip auto-refresh; the dev server updates itself.</span></span>
        </label>
        <div className="flex gap-1 px-2 pb-1 pt-1 md:hidden">
          {DEVICES.map((d) => (
            <button key={d.id} type="button" onClick={() => setPreviewPrefs({ device: d.id })}
              className={clsx('flex flex-1 items-center justify-center gap-1 rounded-md py-1 text-[11px]', pp.device === d.id ? 'bg-pink/15 text-hot' : 'text-muted hover:bg-white/5')}>
              <d.icon size={12} /> {d.id}
            </button>
          ))}
        </div>
      </Popover>

      {/* viewport */}
      <div className="nxw-grid relative min-h-0 flex-1 overflow-auto bg-bg">
        {running ? (
          <div className={clsx('mx-auto h-full transition-[width] duration-300', dev.w ? 'py-4' : '')} style={{ width: dev.w ? dev.w : '100%', maxWidth: '100%' }}>
            <div className={clsx('relative h-full overflow-hidden bg-white', dev.w ? 'rounded-[18px] border border-line shadow-[0_0_0_6px_rgba(255,255,255,.02),0_0_60px_-20px_rgba(255,62,138,.5)]' : '')}>
              <iframe
                ref={iframe} key={project?.slug} src={src} title="Preview" onLoad={onLoad}
                sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-modals"
                className="h-full w-full border-0 bg-white"
              />
              {flash > 0 && <div key={flash} className="nxw-preview-flash pointer-events-none absolute inset-0" />}
            </div>
          </div>
        ) : (
          <div className="flex h-full flex-col items-center justify-center px-8 text-center">
            <div className="relative mb-5">
              <div className="absolute -inset-4 rounded-full bg-pink/10 blur-2xl" />
              <div className="relative flex h-16 w-16 items-center justify-center rounded-2xl border border-line bg-panel2/80">
                <Globe size={26} className="text-pink/70" />
              </div>
            </div>
            {hasFiles ? (
              <>
                <div className="text-[15px] text-ink">Preview is offline</div>
                <p className="mt-1.5 max-w-xs text-[13px] text-muted">Start the dev server to see your app live here. It reloads as Claude edits.</p>
                {canEdit && (
                  <div className="mt-5 flex flex-wrap justify-center gap-2">
                    <button type="button" onClick={() => previewAction('start')} disabled={busy}
                      className="inline-flex items-center gap-2 rounded-full bg-gradient-to-r from-pink to-hot px-4 py-2 text-[13px] font-medium text-black shadow-[0_0_24px_-4px_rgba(255,62,138,.8)] transition hover:scale-[1.03] disabled:opacity-50">
                      {busy ? <span className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-black/30 border-t-black" /> : <Play size={14} fill="currentColor" />} Start preview
                    </button>
                    <button type="button" onClick={(e) => { const p = 'Start the dev server for this project on the assigned preview port so it shows in the preview.'; e.altKey || e.shiftKey ? setDraft(p) : send(p); }}
                      className="inline-flex items-center gap-1.5 rounded-full border border-line px-3.5 py-2 text-[13px] text-ink/90 transition hover:border-pink/40 hover:bg-pink/5">
                      <Zap size={13} className="text-pink" /> Ask Claude to start it
                    </button>
                  </div>
                )}
              </>
            ) : (
              <>
                <div className="text-[15px] text-ink">Nothing to preview yet</div>
                <p className="mt-1.5 max-w-xs text-[13px] text-muted">Ask Claude to build something — it'll appear here.</p>
                {canEdit && (
                  <button type="button" onClick={(e) => { const p = 'Build a polished single-page web app for this project (Vite + React), then start the preview server on the assigned port.'; e.altKey || e.shiftKey ? setDraft(p) : send(p); }}
                    className="mt-5 inline-flex items-center gap-1.5 rounded-full border border-pink/40 bg-pink/10 px-3.5 py-2 text-[13px] text-hot transition hover:bg-pink/20 hover:shadow-[0_0_20px_-4px_rgba(255,62,138,.7)]">
                    <Sparkles size={14} /> Build me a starter app
                  </button>
                )}
              </>
            )}
          </div>
        )}
      </div>

      {/* logs drawer */}
      <div className={clsx('grid shrink-0 transition-[grid-template-rows] duration-300', logsOpen ? 'grid-rows-[1fr]' : 'grid-rows-[0fr]')}>
        <div className="overflow-hidden">
          <div className="flex h-56 flex-col border-t border-line bg-[#050307]">
            <div className="flex h-8 shrink-0 items-center gap-2 px-3 text-[11px] uppercase tracking-[.14em] text-muted">
              <ScrollText size={12} /> Server logs
              {preview?.pid && <span className="font-mono normal-case tracking-normal text-muted/60">pid {preview.pid}</span>}
              <button type="button" onClick={() => refreshPreview()} className="ml-auto rounded p-1 hover:bg-white/5 hover:text-ink"><RotateCw size={11} /></button>
            </div>
            <LogTail text={preview?.logTail ?? ''} />
          </div>
        </div>
      </div>
    </div>
  );
}

function LogTail({ text }: { text: string }) {
  const ref = useRef<HTMLPreElement>(null);
  useEffect(() => { const el = ref.current; if (el) el.scrollTop = el.scrollHeight; }, [text]);
  return (
    <pre ref={ref} className="nxw-scroll min-h-0 flex-1 overflow-auto px-3 pb-3 font-mono text-[11.5px] leading-relaxed text-ink/75 whitespace-pre-wrap">
      {text || <span className="text-muted/60">No output yet.</span>}
    </pre>
  );
}

