// Lazy-loaded: pulls in Monaco. Do not import this file eagerly.
import './monacoSetup';
import { useEffect, useRef } from 'react';
import Editor, { type OnMount } from '@monaco-editor/react';
import type * as Monaco from 'monaco-editor';
import clsx from 'clsx';
import { Circle, Code as CodeIcon, Lock, RotateCw, Save, Sparkles, TriangleAlert, X } from 'lucide-react';
import { useWs } from './store';
import { langFromPath, IMAGE_RE } from './toolFormat';
import { IconBtn, Spin, modKey } from './ui';

export default function CodePane() {
  const tabs = useWs((s) => s.tabs);
  const activeTab = useWs((s) => s.activeTab);
  const canEdit = useWs((s) => s.canEdit);
  const project = useWs((s) => s.project);
  const { setTabContent, saveTab, closeTab, set, reloadTab, keepMine } = useWs.getState();
  const tab = tabs.find((t) => t.path === activeTab) ?? null;
  const editorRef = useRef<Monaco.editor.IStandaloneCodeEditor | null>(null);
  const monacoRef = useRef<typeof Monaco | null>(null);
  const decos = useRef<Monaco.editor.IEditorDecorationsCollection | null>(null);
  const tabsBar = useRef<HTMLDivElement>(null);

  const onMount: OnMount = (editor, monaco) => {
    editorRef.current = editor;
    monacoRef.current = monaco as unknown as typeof Monaco;
    editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyS, () => { useWs.getState().saveTab(); });
    decos.current = editor.createDecorationsCollection([]);
  };

  // "updated by Claude" line highlight
  useEffect(() => {
    const ed = editorRef.current, m = monacoRef.current;
    if (!ed || !m || !tab?.flashAt || !tab.flashLines?.length) return;
    if (Date.now() - tab.flashAt > 6000) return;
    const t = window.setTimeout(() => {
      decos.current?.set(tab.flashLines!.map((ln) => ({
        range: new m.Range(ln, 1, ln, 1),
        options: { isWholeLine: true, className: 'nxw-line-changed', linesDecorationsClassName: 'nxw-line-changed-gutter', overviewRuler: { color: '#ff3e8a', position: m.editor.OverviewRulerLane.Left } },
      })));
      ed.revealLineInCenterIfOutsideViewport(tab.flashLines![0]);
    }, 30);
    const clear = window.setTimeout(() => decos.current?.clear(), 5000);
    return () => { window.clearTimeout(t); window.clearTimeout(clear); };
