                <button type="button" onClick={(e) => { e.stopPropagation(); if (!d || window.confirm(`Discard unsaved changes to ${name}?`)) closeTab(t.path); }}
                  className="flex h-5 w-5 items-center justify-center rounded text-muted hover:bg-white/10 hover:text-ink">
                  {d ? <><Circle size={8} fill="currentColor" className="text-hot group-hover:hidden" /><X size={12} className="hidden group-hover:block" /></> : <X size={12} className={clsx(!active && 'opacity-0 group-hover:opacity-100')} />}
                </button>
              </div>
            );
          })}
        </div>
        <div className="flex shrink-0 items-center gap-1 px-2">
          {!canEdit && <span className="inline-flex items-center gap-1 rounded-md bg-white/[.04] px-2 py-0.5 text-[11px] text-muted"><Lock size={11} /> Read-only</span>}
          {canEdit && tab && (
            <IconBtn label="Save" kbd={`${modKey}S`} onClick={() => saveTab()} disabled={!dirty || tab.saving} glow={dirty}>
              {tab.saving ? <Spin className="h-3 w-3" /> : <Save size={14} />}
