import './workspace.css';
import { lazy, Suspense, useEffect, useMemo, useRef, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import clsx from 'clsx';
import {
  ArrowLeft, Code as CodeIcon, FolderOpen, Globe, MessageSquare, PanelLeft, PanelRight, Upload, Wifi, WifiOff, Circle,
} from 'lucide-react';
import { Group, Panel, Separator, useDefaultLayout, usePanelRef } from 'react-resizable-panels';
import { live } from '@/lib/ws';
import { useAuth } from '@/stores/auth';
import { useWs, isTerminal, type MobileTab } from './store';
import { Chat } from './Chat';
import { LeftRail } from './LeftRail';
import { PreviewPane } from './PreviewPane';
import { Dot, IconBtn, Spin, Tip, useMediaQuery, modKey } from './ui';
import { fmtTokens } from './toolFormat';

const CodePane = lazy(() => import('./CodePane'));

function TopBar({ compact }: { compact?: boolean }) {
  const project = useWs((s) => s.project);
  const connected = useWs((s) => s.connected);
  const usage = useWs((s) => s.usage);
  const leftCollapsed = useWs((s) => s.leftCollapsed);
  const rightCollapsed = useWs((s) => s.rightCollapsed);
  const preview = useWs((s) => s.preview);
  const running = useWs((s) => s.items.some((i) => i.runId && s.runs[i.runId] && !isTerminal(s.runs[i.runId].status)));
  const errored = useWs((s) => { const l = [...s.items].reverse().find((i) => i.runId); return !!(l && s.runs[l.runId!]?.status === 'error'); });
  const set = useWs((s) => s.set);
  const color = project?.color || 'var(--pink)';
  const used = usage ? (usage.today.inputTokens || 0) + (usage.today.outputTokens || 0) : 0;
  const limit = usage?.limits?.dailyTokens ?? null;
  const pct = limit ? Math.min(1, used / limit) : null;

  return (
    <header className="relative z-20 flex h-12 shrink-0 items-center gap-2 border-b border-line/80 bg-panel/70 px-2 backdrop-blur-md sm:px-3">
      <Tip label="Back to Nexus" side="bottom">
        <Link to="/" className="flex h-8 items-center gap-1.5 rounded-lg px-2 text-[12px] text-muted transition-colors hover:bg-white/5 hover:text-ink">
          <ArrowLeft size={15} /><span className="hidden font-display tracking-[.18em] sm:inline">NEXUS</span>
        </Link>
      </Tip>
      <span className="text-muted/40">/</span>
      <div className="flex min-w-0 items-center gap-2">
        <span className="h-2.5 w-2.5 shrink-0 rounded-full" style={{ background: color, boxShadow: `0 0 12px ${color}` }} />
        <span className="truncate font-display text-[13px] tracking-[.1em] text-ink">{project?.name ?? '…'}</span>
        {project?.myRole === 'viewer' && <span className="rounded border border-line px-1.5 text-[10px] uppercase tracking-wider text-muted">viewer</span>}
      </div>
      <Tip label={running ? 'Claude is working' : errored ? 'Last run failed' : 'Idle'} side="bottom">
        <span className="ml-1 flex items-center gap-1.5 rounded-full border border-line/70 px-2 py-0.5 text-[11px] text-muted">
          <Dot tone={running ? 'pink' : errored ? 'bad' : 'ok'} pulse={running} />
          <span className="hidden sm:inline">{running ? 'working' : errored ? 'error' : 'idle'}</span>
        </span>
      </Tip>

      <div className="ml-auto flex items-center gap-1.5">
        {usage && (
          <Tip label={limit ? `Today: ${used.toLocaleString()} / ${limit.toLocaleString()} tokens` : `Today: ${used.toLocaleString()} tokens · ${usage.today.runs} runs`} side="bottom">
            <div className="hidden items-center gap-2 rounded-lg px-2 py-1 text-[11px] text-muted md:flex">
              <span className="font-mono">{fmtTokens(used)}{limit ? ` / ${fmtTokens(limit)}` : ''}</span>
              {pct != null && (
                <div className="h-1 w-16 overflow-hidden rounded-full bg-white/[.06]">
                  <div className={clsx('h-full rounded-full', pct > 0.9 ? 'bg-bad' : pct > 0.7 ? 'bg-warn' : 'bg-gradient-to-r from-pink to-warm')} style={{ width: `${pct * 100}%` }} />
                </div>
              )}
            </div>
          </Tip>
        )}
        {preview?.running && !compact && (
          <Tip label={`Preview running on :${preview.port}`} side="bottom"><span className="hidden items-center gap-1 text-[11px] text-ok/80 lg:flex"><Globe size={12} /> live</span></Tip>
        )}
        <Tip label={connected ? 'Live connection' : 'Reconnecting…'} side="bottom">
          <span className={clsx('flex h-7 w-7 items-center justify-center rounded-md', connected ? 'text-ok/80' : 'text-warn')}>
            {connected ? <Wifi size={14} /> : <WifiOff size={14} className="animate-pulse" />}
          </span>
        </Tip>
        {!compact && (
          <>
            <IconBtn label="Toggle sidebar" kbd={`${modKey}B`} side="bottom" active={!leftCollapsed} onClick={() => set('leftCollapsed', !leftCollapsed)}><PanelLeft size={15} /></IconBtn>
            <IconBtn label="Toggle preview / code" kbd={`${modKey}J`} side="bottom" active={!rightCollapsed} onClick={() => set('rightCollapsed', !rightCollapsed)}><PanelRight size={15} /></IconBtn>
          </>
        )}
      </div>
    </header>
  );
}

function RightPane({ hideTabs }: { hideTabs?: boolean }) {
  const rightTab = useWs((s) => s.rightTab);
  const dirtyCount = useWs((s) => s.tabs.filter((t) => t.content !== t.saved).length);
  const tabCount = useWs((s) => s.tabs.length);
  const previewRunning = useWs((s) => !!s.preview?.running);
  const setRightTab = useWs((s) => s.setRightTab);
  const [codeMounted, setCodeMounted] = useState(rightTab === 'code');
  useEffect(() => { if (rightTab === 'code') setCodeMounted(true); }, [rightTab]);
  return (
    <div className="flex h-full min-h-0 flex-col bg-panel/40">
      {!hideTabs && (
        <div className="flex h-10 shrink-0 items-end gap-1 border-b border-line/70 px-2">
          {(['preview', 'code'] as const).map((t) => (
            <button key={t} type="button" onClick={() => setRightTab(t)}
              className={clsx('relative -mb-px flex h-9 items-center gap-1.5 px-3 text-[12.5px] transition-colors', rightTab === t ? 'text-ink' : 'text-muted hover:text-ink')}>
              {t === 'preview' ? <Globe size={14} /> : <CodeIcon size={14} />}
              {t === 'preview' ? 'Preview' : 'Code'}
              {t === 'preview' && previewRunning && <span className="h-1.5 w-1.5 rounded-full bg-ok shadow-[0_0_6px_var(--success)]" />}
              {t === 'code' && tabCount > 0 && <span className="rounded-full bg-white/[.06] px-1.5 text-[10px] text-muted">{tabCount}</span>}
              {t === 'code' && dirtyCount > 0 && <Circle size={7} fill="currentColor" className="text-hot" />}
              {rightTab === t && <span className="absolute inset-x-2 bottom-0 h-[2px] rounded-full bg-pink shadow-[0_0_10px_var(--pink)]" />}
            </button>
          ))}
        </div>
      )}
      <div className="relative min-h-0 flex-1">
        <div className={clsx('absolute inset-0', rightTab !== 'preview' && 'invisible')}><PreviewPane /></div>
        {codeMounted && (
          <div className={clsx('absolute inset-0', rightTab !== 'code' && 'invisible')}>
            <Suspense fallback={<div className="flex h-full items-center justify-center gap-2 text-[12px] text-muted"><Spin /> Loading editor…</div>}>
              <CodePane />
            </Suspense>
          </div>
        )}
      </div>
    </div>
  );
}

