            <div className={clsx('absolute inset-0', mobileTab !== 'files' && 'invisible')}><LeftRail /></div>
            {(mobileTab === 'preview' || mobileTab === 'code') && (
              <div className="absolute inset-0"><RightPaneMobile tab={mobileTab} /></div>
            )}
          </div>
          <nav className="flex h-14 shrink-0 items-stretch border-t border-line/80 bg-panel/80 backdrop-blur pb-[env(safe-area-inset-bottom)]">
            {MOBILE_TABS.map((t) => (
              <button key={t.id} type="button" onClick={() => set('mobileTab', t.id)}
                className={clsx('relative flex flex-1 flex-col items-center justify-center gap-0.5 text-[10.5px] transition-colors', mobileTab === t.id ? 'text-hot' : 'text-muted')}>
                {mobileTab === t.id && <span className="absolute inset-x-6 top-0 h-[2px] rounded-full bg-pink shadow-[0_0_10px_var(--pink)]" />}
                <t.icon size={18} />{t.label}
              </button>
            ))}
          </nav>
        </div>
      );
    }
    return (
      <Group orientation="horizontal" id="nxw-main" defaultLayout={layout.defaultLayout} onLayoutChanged={layout.onLayoutChanged} className="min-h-0 flex-1">
        <Panel id="left" panelRef={leftRef} collapsible collapsedSize={0} minSize={200} maxSize="40%" defaultSize="19%"
          onResize={(sz) => { const c = sz.inPixels < 2; if (c !== useWs.getState().leftCollapsed) set('leftCollapsed', c); }}>
          <div className="h-full border-r border-line/70"><LeftRail /></div>
        </Panel>
        <Separator className="nxw-sep" />
        <Panel id="center" minSize={380}>
          <div className="h-full min-w-0 bg-bg/40"><Chat /></div>
        </Panel>
        <Separator className="nxw-sep" />
        <Panel id="right" panelRef={rightRef} collapsible collapsedSize={0} minSize={320} defaultSize="38%"
          onResize={(sz) => { const c = sz.inPixels < 2; if (c !== useWs.getState().rightCollapsed) set('rightCollapsed', c); }}>
          <div className="h-full border-l border-line/70"><RightPane /></div>
        </Panel>
      </Group>
    );
  }, [isNarrow, mobileTab, layout.defaultLayout, layout.onLayoutChanged, leftRef, rightRef, set]);

  if (projectError) {
    return (
      <div className="nxw-root flex h-full min-h-screen flex-col items-center justify-center gap-4 bg-bg text-center">
        <div className="font-display text-xl tracking-[.14em] text-pink">ACCESS NODE NOT FOUND</div>
        <p className="max-w-sm text-sm text-muted">{projectError}</p>
        <Link to="/" className="inline-flex items-center gap-2 rounded-full border border-pink/40 px-4 py-2 text-sm text-hot hover:bg-pink/10"><ArrowLeft size={14} /> Back to Nexus</Link>
      </div>
    );
  }
  if (!project) {
    return (
      <div className="nxw-root flex h-full min-h-screen items-center justify-center bg-bg">
        <div className="flex flex-col items-center gap-3 text-[12px] uppercase tracking-[.2em] text-muted"><Spin className="h-6 w-6" /> <span className="nxw-shimmer">Linking project…</span></div>
      </div>
    );
  }

  return (
    <div className={clsx('nxw-root flex h-[100dvh] w-full flex-col overflow-hidden bg-bg text-ink', !canEdit && 'nxw-readonly')}>
      <TopBar compact={isNarrow} />
      {body}
      <DropOverlay show={dragging} />
    </div>
  );
}

function RightPaneMobile({ tab }: { tab: 'preview' | 'code' }) {
  const rightTab = useWs((s) => s.rightTab);
  const setRightTab = useWs((s) => s.setRightTab);
  useEffect(() => { if (rightTab !== tab) setRightTab(tab); }, [tab, rightTab, setRightTab]);
  return <RightPane hideTabs />;
}

