/* Workspace-scoped styles. Everything is prefixed with .nxw- to avoid collisions. */

.nxw-root { font-family: 'Space Grotesk', system-ui, sans-serif; }
.nxw-root ::selection { background: rgba(255, 62, 138, .35); }

/* scrollbars */
.nxw-scroll { scrollbar-width: thin; scrollbar-color: rgba(255, 62, 138, .18) transparent; }
.nxw-scroll::-webkit-scrollbar { width: 8px; height: 8px; }
.nxw-scroll::-webkit-scrollbar-thumb { background: rgba(255, 62, 138, .16); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
.nxw-scroll::-webkit-scrollbar-thumb:hover { background-color: rgba(255, 62, 138, .32); }
.nxw-noscrollbar { scrollbar-width: none; }
.nxw-noscrollbar::-webkit-scrollbar { display: none; }

/* resize separators */
.nxw-sep { position: relative; width: 1px; background: transparent; outline: none; }
.nxw-sep::after {
  content: ''; position: absolute; inset: 0 -2px; background: transparent; transition: background .15s, box-shadow .15s;
}
.nxw-sep:hover::after, .nxw-sep[data-separator='active']::after, .nxw-sep:focus-visible::after {
  background: var(--pink); box-shadow: 0 0 12px var(--pink);
}

/* subtle grid for empty viewports */
.nxw-grid {
  background-image:
    linear-gradient(rgba(255, 62, 138, .035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 62, 138, .035) 1px, transparent 1px);
  background-size: 28px 28px;
  background-position: -1px -1px;
}

/* animations */
@keyframes nxw-fade-in { from { opacity: 0; transform: translateY(3px); } to { opacity: 1; transform: none; } }
.nxw-fade-in { animation: nxw-fade-in .22s ease-out both; }
.nxw-pop { animation: nxw-fade-in .14s ease-out both; }

@keyframes nxw-shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
.nxw-shimmer {
  background: linear-gradient(90deg, var(--muted) 0%, var(--muted) 35%, var(--hot-pink) 50%, var(--muted) 65%, var(--muted) 100%);
  background-size: 200% 100%;
  -webkit-background-clip: text; background-clip: text; color: transparent !important;
  animation: nxw-shimmer 2.2s linear infinite;
}
@keyframes nxw-breathe { 0%, 100% { opacity: .55; filter: drop-shadow(0 0 0 transparent); } 50% { opacity: 1; filter: drop-shadow(0 0 5px var(--pink)); } }
.nxw-breathe { animation: nxw-breathe 1.8s ease-in-out infinite; }

@keyframes nxw-caret { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }
.nxw-caret {
  display: inline-block; width: .5em; height: 1.05em; margin-left: 2px; vertical-align: -0.15em;
  background: var(--pink); box-shadow: 0 0 8px var(--pink); animation: nxw-caret 1s steps(1) infinite;
}
.nxw-streaming > :last-child::after,
.nxw-streaming > :last-child > li:last-child::after {
  content: ''; display: inline-block; width: .5em; height: 1.05em; margin-left: 3px; vertical-align: -0.15em;
  background: var(--pink); box-shadow: 0 0 8px var(--pink); animation: nxw-caret 1s steps(1) infinite;
}
.nxw-streaming > ul:last-child::after, .nxw-streaming > ol:last-child::after, .nxw-streaming > div:last-child::after { display: none; }

@keyframes nxw-flash { 0% { background: rgba(255, 62, 138, .32); box-shadow: inset 2px 0 0 var(--pink); } 100% { background: transparent; box-shadow: inset 2px 0 0 transparent; } }
.nxw-flash { animation: nxw-flash 1.8s ease-out both; }
.nxw-flash > span { color: var(--hot-pink); }

@keyframes nxw-preview-flash { 0% { box-shadow: inset 0 0 0 2px var(--pink), inset 0 0 40px rgba(255, 62, 138, .35); } 100% { box-shadow: inset 0 0 0 2px transparent; } }
.nxw-preview-flash { animation: nxw-preview-flash 1.2s ease-out both; }

@keyframes nxw-drop { 0%, 100% { box-shadow: 0 0 30px -6px rgba(255, 62, 138, .6), inset 0 0 30px -6px rgba(255, 62, 138, .4); } 50% { box-shadow: 0 0 60px -2px rgba(255, 62, 138, .9), inset 0 0 50px -6px rgba(255, 62, 138, .6); } }
.nxw-drop { animation: nxw-drop 1.6s ease-in-out infinite; }

@keyframes nxw-ring { 0% { box-shadow: 0 0 0 0 rgba(255, 62, 138, .55); } 100% { box-shadow: 0 0 0 9px rgba(255, 62, 138, 0); } }
.nxw-ring { animation: nxw-ring 1.6s ease-out infinite; }

/* Monaco decorations */
.nxw-line-changed { background: rgba(255, 62, 138, .14); animation: nxw-line 5s ease-out forwards; }
.nxw-line-changed-gutter { background: var(--pink); width: 3px !important; margin-left: 3px; box-shadow: 0 0 6px var(--pink); }
@keyframes nxw-line { 0% { background: rgba(255, 62, 138, .32); } 100% { background: rgba(255, 62, 138, 0); } }

/* ---------------- Markdown ---------------- */
.nxw-md { font-size: 14.5px; line-height: 1.7; color: var(--text); overflow-wrap: anywhere; }
.nxw-md > :first-child { margin-top: 0; }
.nxw-md > :last-child { margin-bottom: 0; }
.nxw-md p { margin: .55em 0; }
.nxw-md h1, .nxw-md h2, .nxw-md h3, .nxw-md h4 { font-weight: 600; line-height: 1.3; margin: 1.2em 0 .5em; color: #fff; }
.nxw-md h1 { font-size: 1.35em; }
.nxw-md h2 { font-size: 1.18em; }
.nxw-md h3 { font-size: 1.05em; }
.nxw-md h4 { font-size: 1em; color: var(--hot-pink); }
.nxw-md h1, .nxw-md h2 { padding-bottom: .25em; border-bottom: 1px solid var(--border); }
.nxw-md ul, .nxw-md ol { margin: .5em 0; padding-left: 1.4em; }
.nxw-md ul { list-style: none; }
.nxw-md ul > li { position: relative; }
.nxw-md ul > li::before { content: ''; position: absolute; left: -1em; top: .72em; width: 5px; height: 5px; border-radius: 1px; background: var(--pink); opacity: .7; transform: rotate(45deg); }
.nxw-md ul > li.task-list-item::before { display: none; }
.nxw-md ul > li.task-list-item { margin-left: -1.2em; }
.nxw-md ol { list-style: decimal; }
.nxw-md ol > li::marker { color: var(--pink); font-family: 'JetBrains Mono', monospace; font-size: .85em; }
.nxw-md li { margin: .22em 0; }
.nxw-md li > p { margin: .2em 0; }
.nxw-md a { color: var(--hot-pink); text-decoration: underline; text-decoration-color: rgba(255, 111, 174, .35); text-underline-offset: 3px; }
.nxw-md a:hover { text-decoration-color: var(--hot-pink); }
.nxw-md strong { color: #fff; font-weight: 600; }
.nxw-md em { color: #f9d6e6; }
.nxw-md blockquote { margin: .8em 0; padding: .2em 1em; border-left: 2px solid var(--pink); color: var(--muted); background: rgba(255, 62, 138, .04); border-radius: 0 8px 8px 0; }
.nxw-md hr { border: 0; height: 1px; margin: 1.4em 0; background: linear-gradient(90deg, transparent, var(--border), var(--pink), var(--border), transparent); opacity: .7; }
.nxw-md :not(pre) > code {
  font-family: 'JetBrains Mono', monospace; font-size: .86em; padding: .12em .4em; border-radius: 5px;
  background: rgba(255, 62, 138, .08); border: 1px solid rgba(255, 62, 138, .14); color: #ffb3d3;
}
.nxw-md code.nxw-path { cursor: pointer; transition: all .15s; }
.nxw-md code.nxw-path:hover { background: rgba(255, 62, 138, .18); border-color: rgba(255, 62, 138, .5); color: #fff; box-shadow: 0 0 10px -2px rgba(255, 62, 138, .6); }
.nxw-md img { max-width: 100%; border-radius: 10px; border: 1px solid var(--border); }
.nxw-table { margin: .8em 0; overflow-x: auto; border: 1px solid var(--border); border-radius: 10px; }
.nxw-md table { width: 100%; border-collapse: collapse; font-size: .92em; }
.nxw-md th { text-align: left; font-weight: 600; color: var(--hot-pink); background: rgba(255, 62, 138, .05); }
.nxw-md th, .nxw-md td { padding: .45em .8em; border-bottom: 1px solid var(--border); }
.nxw-md tr:last-child td { border-bottom: 0; }
.nxw-md input[type='checkbox'] { accent-color: var(--pink); margin-right: .4em; }
.nxw-interim .nxw-md { font-size: 13.5px; color: rgba(246, 233, 240, .82); }

/* code blocks */
.nxw-code { margin: .9em 0; border: 1px solid var(--border); border-radius: 12px; overflow: hidden; background: #0a070d; box-shadow: 0 0 0 1px rgba(255, 62, 138, .03), 0 12px 30px -18px rgba(0, 0, 0, .9); }
.nxw-code-head { display: flex; align-items: center; justify-content: space-between; padding: 4px 6px 4px 12px; background: linear-gradient(90deg, rgba(255, 62, 138, .07), transparent 60%); border-bottom: 1px solid var(--border); }
.nxw-code pre { margin: 0; padding: 12px 14px; overflow-x: auto; font-family: 'JetBrains Mono', monospace; font-size: 12.5px; line-height: 1.6; scrollbar-width: thin; scrollbar-color: rgba(255, 62, 138, .2) transparent; }
.nxw-code pre code { background: none; border: 0; padding: 0; color: #f6e9f0; }

/* highlight.js — pink/black */
.nxw-md .hljs { color: #f6e9f0; background: transparent; }
.nxw-md .hljs-comment, .nxw-md .hljs-quote { color: #7d6472; font-style: italic; }
.nxw-md .hljs-keyword, .nxw-md .hljs-selector-tag, .nxw-md .hljs-meta .hljs-keyword, .nxw-md .hljs-doctag, .nxw-md .hljs-section { color: #ff6fae; }
.nxw-md .hljs-string, .nxw-md .hljs-meta .hljs-string, .nxw-md .hljs-regexp, .nxw-md .hljs-addition { color: #ffb38f; }
.nxw-md .hljs-number, .nxw-md .hljs-literal, .nxw-md .hljs-symbol, .nxw-md .hljs-bullet { color: #ffc857; }
.nxw-md .hljs-title, .nxw-md .hljs-title.function_, .nxw-md .hljs-function .hljs-title { color: #ff9cc6; }
.nxw-md .hljs-title.class_, .nxw-md .hljs-type, .nxw-md .hljs-built_in, .nxw-md .hljs-class .hljs-title { color: #d08cff; }
.nxw-md .hljs-attr, .nxw-md .hljs-attribute, .nxw-md .hljs-variable, .nxw-md .hljs-template-variable, .nxw-md .hljs-property { color: #ff8fc0; }
.nxw-md .hljs-params { color: #f6e9f0; }
.nxw-md .hljs-tag, .nxw-md .hljs-name { color: #ff6fae; }
.nxw-md .hljs-selector-id, .nxw-md .hljs-selector-class, .nxw-md .hljs-selector-attr, .nxw-md .hljs-selector-pseudo { color: #ff8a5c; }
.nxw-md .hljs-meta { color: #b14bff; }
.nxw-md .hljs-deletion { color: #ff4d6d; background: rgba(255, 77, 109, .08); }
.nxw-md .hljs-addition { background: rgba(61, 255, 181, .06); color: #3dffb5; }
.nxw-md .hljs-emphasis { font-style: italic; }
.nxw-md .hljs-strong { font-weight: 700; }
.nxw-md .hljs-punctuation, .nxw-md .hljs-operator { color: #c79ab2; }

