// Run: node --test src/features/workspace/reducer.test.mjs   (Node >= 22.18 strips TS types natively)
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { applyRunEvent, emptyRun, replay, splitFinal, segments, cleanText, editStats, changedLines, translateThinking } from './reducer.ts';

const ev = (seq, type, data, ts) => ({ seq, type, data, ts });

test('streams thinking then text, closing thinking with duration', () => {
  let s = emptyRun('r1', 'queued');
  s = applyRunEvent(s, ev(0, 'init', { sessionId: 'S', model: 'opus', tools: [], cwd: '/w' }), 1000);
  assert.equal(s.status, 'running');
  s = applyRunEvent(s, ev(1, 'thinking', { delta: 'Let me look ' }), 1000);
  s = applyRunEvent(s, ev(2, 'thinking', { delta: 'at the code.' }), 2000);
  s = applyRunEvent(s, ev(3, 'text', { delta: 'Hello' }), 5000);
  s = applyRunEvent(s, ev(4, 'text', { delta: ' world' }), 5100);
  assert.equal(s.blocks.length, 2);
  assert.deepEqual(s.blocks[0], { kind: 'thinking', text: 'Let me look at the code.', startedAt: 1000, endedAt: 5000, done: true });
  assert.equal(s.blocks[1].text, 'Hello world');
  assert.equal(s.blocks[1].done, false);
});

test('dedupes replayed seqs and does not mutate input', () => {
  const a = applyRunEvent(emptyRun('r'), ev(0, 'text', { delta: 'x' }), 0);
  const frozen = JSON.stringify(a);
  const b = applyRunEvent(a, ev(0, 'text', { delta: 'x' }), 0);
  assert.equal(b, a);
  const c = applyRunEvent(a, ev(1, 'text', { delta: 'y' }), 0);
  assert.equal(JSON.stringify(a), frozen);
  assert.equal(c.blocks[0].text, 'xy');
});

test('pairs tool_use with tool_result, todos, usage, result and done', () => {
  const s = replay('r', [
    ev(0, 'text', { delta: 'Working on it.' }),
    ev(1, 'tool_use', { id: 't1', name: 'Read', input: { file_path: '/workspace/projects/a/src/App.tsx' } }),
    ev(2, 'tool_use', { id: 't2', name: 'TodoWrite', input: { todos: [{ content: 'a', status: 'in_progress' }] } }),
    ev(3, 'tool_result', { id: 't1', isError: false, content: 'file body' }),
    ev(4, 'todo', { todos: [{ content: 'a', status: 'completed' }] }),
    ev(5, 'usage', { inputTokens: 10, outputTokens: 5, cacheReadTokens: 0, cacheWriteTokens: 0 }),
    ev(6, 'usage', { inputTokens: 1, outputTokens: 2, cacheReadTokens: 3, cacheWriteTokens: 4 }),
    ev(7, 'text', { delta: 'Done!<nx-suggestions>[{"label":"x"}]</nx-suggestions>' }),
    ev(8, 'result', { sessionId: 'S', isError: false, result: 'Done!', durationMs: 1234, numTurns: 2, costUsd: 0.01, usage: { inputTokens: 11, outputTokens: 7, cacheReadTokens: 3, cacheWriteTokens: 4 } }),
    ev(9, 'done', { exitCode: 0 }),
  ]);
  assert.equal(s.status, 'done');
  const tools = s.blocks.filter((b) => b.kind === 'tool');
  assert.equal(tools.length, 2);
  assert.equal(tools[0].result.content, 'file body');
  assert.deepEqual(s.todos, [{ content: 'a', status: 'completed' }]);
  assert.equal(s.usage.outputTokens, 7);
  const { process, final } = splitFinal(s.blocks);
  assert.equal(final.length, 1);
  assert.equal(cleanText(final[0].text), 'Done!');
  assert.equal(segments(process).length, 2); // interim text + tool group
  assert.ok(s.blocks.every((b) => b.kind === 'tool' || b.done));
});

test('error and abort statuses', () => {
  let s = replay('r', [ev(0, 'error', { message: 'boom' }), ev(1, 'done', { exitCode: 1 })]);
  assert.equal(s.status, 'error');
  assert.equal(s.error, 'boom');
  s = replay('r', [ev(0, 'text', { delta: 'hi' }), ev(1, 'done', { exitCode: 143 })]);
  assert.equal(s.status, 'aborted');
});

test('helpers', () => {
  assert.equal(cleanText('Answer\n<nx-sugg'), 'Answer');
  assert.deepEqual(editStats('Edit', { old_string: 'a\nb', new_string: 'a\nc\nd' }), { add: 2, del: 1 });
  assert.deepEqual(editStats('Write', { content: '1\n2\n3' }), { add: 3, del: 0 });
  assert.deepEqual(changedLines('a\nb\nc', 'a\nB\nc\nd'), [2, 4]);
  assert.equal(translateThinking('The user wants a button. Let me check the config file.'), 'Checking the config file');
  assert.equal(translateThinking("I'll update the router"), 'Updating the router');
});

