/* Nxeon palette (SPEC §6). Hex vars for direct use, -rgb channel vars for alpha compositing. */
:root {
  --bg: #07050a;        --bg-rgb: 7 5 10;
  --panel: #0f0a12;     --panel-rgb: 15 10 18;
  --panel-2: #160e1a;   --panel-2-rgb: 22 14 26;
  --border: #2a1626;    --border-rgb: 42 22 38;
  --text: #f6e9f0;      --text-rgb: 246 233 240;
  --muted: #a68a99;     --muted-rgb: 166 138 153;
  --pink: #ff3e8a;      --pink-rgb: 255 62 138;
  --hot-pink: #ff6fae;  --hot-pink-rgb: 255 111 174;
  --warm: #ff8a5c;      --warm-rgb: 255 138 92;
  --violet: #b14bff;    --violet-rgb: 177 75 255;
  --success: #3dffb5;   --success-rgb: 61 255 181;
  --warn: #ffc857;      --warn-rgb: 255 200 87;
  --danger: #ff4d6d;    --danger-rgb: 255 77 109;

  --radius: 10px;
  --ease-out: cubic-bezier(.2, .8, .2, 1);
  --topbar-h: 48px;
  color-scheme: dark;
}
@import './theme.css';
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  html, body, #root { height: 100%; }
  body {
    @apply bg-bg text-ink font-sans antialiased;
    font-feature-settings: 'ss01', 'tnum' 0;
    -webkit-tap-highlight-color: transparent;
    overscroll-behavior: none;
  }
  ::selection { background: rgb(var(--pink-rgb) / 0.35); color: var(--text); }
  :focus { outline: none; }
  :focus-visible {
    outline: 1px solid rgb(var(--pink-rgb) / 0.9);
    outline-offset: 2px;
    box-shadow: 0 0 0 4px rgb(var(--pink-rgb) / 0.15);
    border-radius: 6px;
  }
  code, kbd, pre, samp { @apply font-mono; }
  input, textarea, select, button { font: inherit; color: inherit; }
  button { cursor: pointer; }
  button:disabled { cursor: not-allowed; }

  /* Scrollbars */
  * { scrollbar-width: thin; scrollbar-color: rgb(var(--border-rgb)) transparent; }
  ::-webkit-scrollbar { width: 10px; height: 10px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb {
    background: rgb(var(--border-rgb)); border-radius: 10px;
    border: 3px solid transparent; background-clip: padding-box;
  }
  ::-webkit-scrollbar-thumb:hover { background: rgb(var(--pink-rgb) / 0.45); background-clip: padding-box; }
  ::-webkit-scrollbar-corner { background: transparent; }
}

@layer components {
  /* Glass card used for popovers / hover cards */
  .nx-glass {
    background: linear-gradient(180deg, rgb(var(--panel-2-rgb) / 0.86), rgb(var(--panel-rgb) / 0.9));
    backdrop-filter: blur(14px) saturate(130%);
    -webkit-backdrop-filter: blur(14px) saturate(130%);
    border: 1px solid rgb(var(--border-rgb));
    box-shadow: 0 18px 50px -12px rgb(0 0 0 / 0.85), inset 0 1px 0 rgb(255 255 255 / 0.03);
  }
  .nx-panel { @apply bg-panel border border-line rounded-[var(--radius)]; }
  .nx-label { @apply text-[11px] uppercase tracking-[0.14em] text-muted font-medium; }
  .nx-display { @apply font-display uppercase tracking-[0.18em]; }
  .nx-table { @apply w-full text-sm border-collapse; }
  .nx-table th {
    @apply text-left font-medium text-[11px] uppercase tracking-[0.12em] text-muted px-3 py-2 border-b border-line bg-panel sticky top-0 z-[1];
  }
  .nx-table td { @apply px-3 py-2 border-b border-line/60 align-middle; }
  .nx-table tbody tr { @apply transition-colors; }
  .nx-table tbody tr:hover { background: rgb(var(--pink-rgb) / 0.035); }
}

@layer utilities {

/** @type {import('tailwindcss').Config} */
// Colors resolve to CSS vars defined in src/styles/theme.css. Each color has an `--x-rgb` channel
// var so Tailwind opacity modifiers work (e.g. `bg-pink/10`, `border-line/60`).
const c = (n) => `rgb(var(--${n}-rgb) / <alpha-value>)`;
export default {
  content: ['./index.html', './src/**/*.{ts,tsx}'],
  theme: {
    extend: {
      colors: {
        bg: c('bg'), panel: c('panel'), panel2: c('panel-2'), line: c('border'),
        ink: c('text'), muted: c('muted'), pink: c('pink'), hot: c('hot-pink'),
        warm: c('warm'), violet: c('violet'), ok: c('success'), warn: c('warn'), bad: c('danger'),
      },
      fontFamily: {
        sans: ['"Space Grotesk"', 'system-ui', 'sans-serif'],
        mono: ['"JetBrains Mono"', 'ui-monospace', 'monospace'],
        display: ['Orbitron', '"Space Grotesk"', 'sans-serif'],
      },
      boxShadow: {
        glow: '0 0 0 1px rgb(var(--pink-rgb) / 0.35), 0 0 18px -2px rgb(var(--pink-rgb) / 0.45)',
        'glow-sm': '0 0 10px -2px rgb(var(--pink-rgb) / 0.5)',
        panel: '0 10px 40px -10px rgb(0 0 0 / 0.8), 0 0 0 1px rgb(var(--border-rgb) / 1)',
      },
      keyframes: {
        'fade-in': { from: { opacity: 0 }, to: { opacity: 1 } },
        'pop-in': { from: { opacity: 0, transform: 'translateY(4px) scale(0.98)' }, to: { opacity: 1, transform: 'none' } },
        'slide-in-right': { from: { transform: 'translateX(24px)', opacity: 0 }, to: { transform: 'none', opacity: 1 } },
        'pulse-soft': { '0%,100%': { opacity: 1 }, '50%': { opacity: 0.45 } },
        shimmer: { from: { backgroundPosition: '200% 0' }, to: { backgroundPosition: '-200% 0' } },
        blink: { '0%,49%': { opacity: 1 }, '50%,100%': { opacity: 0 } },
      },
      animation: {
        'fade-in': 'fade-in 160ms ease-out',
        'pop-in': 'pop-in 160ms cubic-bezier(.2,.8,.2,1)',
        'slide-in-right': 'slide-in-right 220ms cubic-bezier(.2,.8,.2,1)',
        'pulse-soft': 'pulse-soft 1.6s ease-in-out infinite',
        shimmer: 'shimmer 1.6s linear infinite',
        blink: 'blink 1s step-end infinite',
      },
    },
  },
  plugins: [],
};

