const sockets = new Set();
const send = (ws, m) => ws.readyState === 1 && ws.send(JSON.stringify(m));
const broadcastRun = (runId, m) => { for (const ws of sockets) if (ws.runs?.has(runId)) send(ws, m); };
const broadcastProject = (m) => { for (const ws of sockets) if (ws.projects?.has('p1')) send(ws, m); };

function startRun(convId, text) {
  const runId = 'run' + Math.random().toString(36).slice(2, 8);
  const userMsg = { id: 'm' + Math.random().toString(36).slice(2, 8), conversationId: convId, role: 'user', content: text, attachments: [], runId, createdAt: now() };
  messages[convId].push(userMsg);
  const run = { id: runId, convId, status: 'queued', events: [], startedAt: now() };
  runs[runId] = run;
  const steps = script(text);
  let i = 0; const t0 = Date.now();
  const tick = () => {
    if (run.status === 'aborted') return;
    if (i >= steps.length) return;
    const s = steps[i++];
    if (s.type === '__file') {
      files[s.data.path] = s.data.content;
      broadcastProject({ t: 'file_change', projectId: 'p1', path: s.data.path, kind: s.data.kind });
    } else if (s.type === '__sugg') {
      run.suggestions = s.data.items;
      broadcastRun(runId, { t: 'suggestions', runId, items: s.data.items });
    } else {
      if (s.type === 'result') s.data.durationMs = Date.now() - t0;
      const seq = run.events.length;
      const e = { seq, type: s.type, data: s.data, ts: Date.now() };
      run.events.push(e);
      run.status = 'running';
      broadcastRun(runId, { t: 'run_event', runId, seq, type: s.type, data: s.data });
      if (s.type === 'done') finish(run, 'done');
    }
    setTimeout(tick, (steps[i]?.delay ?? 50) * Number(process.env.SPEED || 1));
  };
  setTimeout(tick, 400);
  return { runId, messageId: userMsg.id };
}
function finish(run, status) {
  run.status = status; run.endedAt = now();
  const final = run.events.filter((e) => e.type === 'text').map((e) => e.data.delta).join('');
  messages[run.convId].push({ id: 'a' + run.id, conversationId: run.convId, role: 'assistant', content: final.replace(/<nx-suggestions>[\s\S]*<\/nx-suggestions>/, ''), attachments: [], runId: run.id, createdAt: now(), suggestions: run.suggestions });
  broadcastRun(run.id, { t: 'run_status', runId: run.id, conversationId: run.convId, projectId: 'p1', status });
}

// seed c1 with a completed run instantly
(function seed() {
  const runId = 'seed1';
  messages.c1.push({ id: 'mu0', conversationId: 'c1', role: 'user', content: 'Build a product grid for the store with neon cards.', attachments: [{ id: 'up1', filename: 'mockup.png', mime: 'image/png', size: 48211, url: '/api/uploads/up1' }], runId, createdAt: now() });
  const run = { id: runId, convId: 'c1', status: 'done', events: [], startedAt: now() };
  let t = Date.now() - 60000;
  for (const s of script('')) {
    t += s.delay * 3;
    if (s.type.startsWith('__')) { if (s.type === '__sugg') run.suggestions = s.data.items; continue; }
    if (s.type === 'result') s.data.durationMs = 47000;
    run.events.push({ seq: run.events.length, type: s.type, data: s.data, ts: t });
  }
  runs[runId] = run;
  finish(run, 'done');
})();

function runDTO(r) {
  return { id: r.id, status: r.status, model: 'opus', mode: 'auto', startedAt: r.startedAt, endedAt: r.endedAt ?? null, inputTokens: 5500, outputTokens: 1320, cacheRead: 0, cacheWrite: 0, costUsd: 0.18, durationMs: 47000 };
}
function msgsFor(convId) {
  return messages[convId].map((m) => m.role === 'assistant' ? { ...m, run: runDTO(runs[m.runId]), events: runs[m.runId].events } : { ...m, run: m.runId && runs[m.runId] ? runDTO(runs[m.runId]) : null });
}

const body = (req) => new Promise((res) => { let d = ''; req.on('data', (c) => (d += c)); req.on('end', () => { try { res(JSON.parse(d || '{}')); } catch { res({ raw: d }); } }); });
const json = (res, code, obj) => { res.writeHead(code, { 'content-type': 'application/json' }); res.end(JSON.stringify(obj)); };

const server = http.createServer(async (req, res) => {
  const u = new URL(req.url, 'http://x');
  const p = u.pathname; const m = req.method;
  if (p.startsWith('/preview/demo')) {
    res.writeHead(200, { 'content-type': 'text/html' });
    return res.end(`<!doctype html><html><body style="margin:0;font-family:sans-serif;background:linear-gradient(135deg,#1a0612,#07050a);color:#fff;min-height:100vh;display:flex;align-items:center;justify-content:center;flex-direction:column"><h1 style="font-size:42px;color:#ff6fae;text-shadow:0 0 20px #ff3e8a">NEON STORE</h1><div style="display:grid;grid-template-columns:repeat(3,120px);gap:16px">${['Visor', 'Jacket', 'Boots'].map((i) => `<div style="border:1px solid #ff3e8a55;border-radius:12px;padding:24px;text-align:center">${i}</div>`).join('')}</div><p style="opacity:.5">${new Date().toLocaleTimeString()}</p></body></html>`);
  }
  if (p === '/api/projects' && m === 'GET') return json(res, 200, [project]);
  if (p === '/api/projects/p1' && m === 'GET') return json(res, 200, project);
  if (p === '/api/models') return json(res, 200, [{ id: 'opus', label: 'Opus 5.5' }, { id: 'sonnet', label: 'Sonnet 5.5' }, { id: 'haiku', label: 'Haiku 4.5' }]);
  if (p === '/api/usage/me') return json(res, 200, { today: { inputTokens: 210000, outputTokens: 43000, cacheReadTokens: 0, cacheWriteTokens: 0, runs: 12, costUsd: 3.2 }, d7: {}, d30: {}, byModel: [], limits: { dailyTokens: 1000000 } });
  if (p === '/api/projects/p1/conversations' && m === 'GET') return json(res, 200, convs);
  if (p === '/api/projects/p1/conversations' && m === 'POST') {
    const b = await body(req);
    const c = { id: 'c' + Math.random().toString(36).slice(2, 6), projectId: 'p1', title: b.title || 'New', model: b.model, mode: b.mode, createdAt: now(), updatedAt: now() };
    convs.unshift(c); messages[c.id] = []; return json(res, 200, c);
  }
  let mm;
  if ((mm = p.match(/^\/api\/conversations\/(\w+)\/messages$/))) return json(res, 200, msgsFor(mm[1]) ?? []);
  if ((mm = p.match(/^\/api\/conversations\/(\w+)\/prompt$/))) {
    const b = await body(req);
    if (process.env.LIMIT) return json(res, 429, { error: { code: 'daily_limit', message: 'You have used 1,000,000 of 1,000,000 tokens today.' } });
    return json(res, 200, startRun(mm[1], b.text));
  }
  if ((mm = p.match(/^\/api\/conversations\/(\w+)$/))) { const b = m === 'PATCH' ? await body(req) : {}; const c = convs.find((x) => x.id === mm[1]); if (c && b.title) c.title = b.title; return json(res, 200, c ?? {}); }
  if ((mm = p.match(/^\/api\/runs\/(\w+)\/abort$/))) {
    const r = runs[mm[1]]; if (r && r.status !== 'done') { r.status = 'aborted'; const seq = r.events.length; r.events.push({ seq, type: 'done', data: { exitCode: 143 } }); broadcastRun(r.id, { t: 'run_event', runId: r.id, seq, type: 'done', data: { exitCode: 143 } }); finish(r, 'aborted'); }
    return json(res, 200, { ok: true });
  }
  if (p === '/api/projects/p1/files/tree') return json(res, 200, tree());
  if (p === '/api/projects/p1/files/content' && m === 'GET') { const f = u.searchParams.get('path'); return f in files ? json(res, 200, { path: f, content: files[f] }) : json(res, 404, { error: { code: 'not_found', message: 'File not found' } }); }
  if (p === '/api/projects/p1/files/content' && m === 'PUT') { const b = await body(req); files[b.path] = b.content; broadcastProject({ t: 'file_change', projectId: 'p1', path: b.path, kind: 'change' }); return json(res, 200, { ok: true }); }
  if (p === '/api/projects/p1/files/delete') { const b = await body(req); delete files[b.path]; return json(res, 200, { ok: true }); }
  if (p === '/api/projects/p1/files/rename') { const b = await body(req); files[b.to] = files[b.from]; delete files[b.from]; return json(res, 200, { ok: true }); }
  if (p === '/api/projects/p1/files/mkdir') { const b = await body(req); files[b.path + '/.keep'] = ''; return json(res, 200, { ok: true }); }
  if (p === '/api/projects/p1/preview/status') return json(res, 200, preview);
  if (p === '/api/projects/p1/preview/start') { preview = { ...preview, running: true }; broadcastProject({ t: 'preview_status', projectId: 'p1', running: true, port: 4101 }); return json(res, 200, preview); }
  if (p === '/api/projects/p1/preview/stop') { preview = { ...preview, running: false }; broadcastProject({ t: 'preview_status', projectId: 'p1', running: false, port: null }); return json(res, 200, preview); }
  if (p === '/api/uploads' && m === 'POST') { await body(req); return json(res, 200, { id: 'up' + Date.now(), filename: 'file', mime: 'application/octet-stream', size: 1000, url: '/api/uploads/x' }); }
  if (p.startsWith('/api/uploads/')) { res.writeHead(200, { 'content-type': 'image/svg+xml' }); return res.end('<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80"><defs><linearGradient id="g"><stop offset="0" stop-color="#ff3e8a"/><stop offset="1" stop-color="#b14bff"/></linearGradient></defs><rect width="80" height="80" fill="url(#g)"/></svg>'); }
  if (p === '/api/transcribe') { await body(req); return json(res, 200, { text: 'make the cards glow on hover' }); }
  json(res, 404, { error: { code: 'not_found', message: p } });
});

const wss = new WebSocketServer({ server, path: '/ws' });
wss.on('connection', (ws) => {
  sockets.add(ws); ws.runs = new Set(); ws.projects = new Set();
  ws.on('close', () => sockets.delete(ws));
  ws.on('message', (raw) => {
    const msg = JSON.parse(raw);
    if (msg.t === 'sub') {
      ws.runs.add(msg.runId);
      const r = runs[msg.runId];
      if (r) for (const e of r.events) if (e.seq >= (msg.fromSeq ?? 0)) send(ws, { t: 'run_event', runId: r.id, seq: e.seq, type: e.type, data: e.data });
    }
    if (msg.t === 'unsub') ws.runs.delete(msg.runId);
    if (msg.t === 'sub_project') ws.projects.add(msg.projectId);
    if (msg.t === 'ping') send(ws, { t: 'pong' });
  });
