import fs from 'node:fs'; fs.mkdirSync(OUT, { recursive: true });
const mode = process.argv[2] || 'all';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1600, height: 960 }, deviceScaleFactor: 1 });
const logs = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') logs.push(m.type() + ': ' + m.text()); });
page.on('pageerror', (e) => logs.push('pageerror: ' + e.message));
await page.goto('http://localhost:5199/p/demo', { waitUntil: 'networkidle' });
await page.waitForTimeout(1500);
await page.screenshot({ path: OUT + '01-history.png' });

if (mode === 'all' || mode === 'process') {
  // expand process of seeded message
  const b = page.getByText(/Worked for/).first();
  if (await b.count()) { await b.click(); await page.waitForTimeout(400); }
  await page.screenshot({ path: OUT + '02-history-expanded.png' });
}

if (mode === 'all' || mode === 'live') {
  await page.getByText('Chats').first().click();
  await page.waitForTimeout(300);
  await page.locator('textarea').fill('Add a product grid with neon cards');
  await page.keyboard.press('Enter');
  await page.waitForTimeout(2600);
  await page.screenshot({ path: OUT + '03-live-thinking.png' });
  await page.waitForTimeout(4000);
  await page.screenshot({ path: OUT + '04-live-tools.png' });
  await page.waitForTimeout(6000);
  await page.screenshot({ path: OUT + '05-live-late.png' });
  await page.waitForTimeout(9000);
  await page.screenshot({ path: OUT + '06-done.png' });
}

if (mode === 'all' || mode === 'code') {
  await page.getByText('Files').first().click();
  await page.waitForTimeout(300);
  await page.locator('[role=treeitem]', { hasText: 'src' }).first().click();
  await page.waitForTimeout(300);
  await page.locator('[role=treeitem]', { hasText: 'App.tsx' }).first().click();
  await page.waitForTimeout(3500);
  await page.screenshot({ path: OUT + '07-code.png' });
  // slash popup
  await page.locator('textarea').fill('/');
  await page.waitForTimeout(300);
  await page.screenshot({ path: OUT + '08-slash.png' });
  await page.locator('textarea').fill('');
  await page.getByRole('button', { name: /Auto/ }).first().click();
  await page.waitForTimeout(300);
  await page.screenshot({ path: OUT + '09-mode.png' });
  await page.keyboard.press('Escape');
}

if (mode === 'all' || mode === 'mobile') {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.waitForTimeout(800);
  await page.screenshot({ path: OUT + '10-mobile.png' });
}
console.log(logs.join('\n'));
await browser.close();

